/* Prometheus Synotrix — Interactive Human Joint Simulator (ES module) */
  
import * as THREE from 'three';  
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';  
  
/* ─── PBR TEXTURE GENERATION ─── */  
function createBoneTextures() {  
  const size = 1024;  
  const canvas = document.createElement('canvas');  
  canvas.width = size; canvas.height = size;  
  const ctx = canvas.getContext('2d');  
  ctx.fillStyle = '#e4dcd0';  
  ctx.fillRect(0,0,size,size);  
  for(let i=0;i<8000;i++){  
    const x=Math.random()*size, y=Math.random()*size, r=Math.random()*1.2;  
    ctx.fillStyle = Math.random()>0.5 ? 'rgba(170,160,140,0.35)' : 'rgba(245,240,232,0.35)';  
    ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.fill();  
  }  
  ctx.strokeStyle='rgba(150,140,120,0.18)'; ctx.lineWidth=0.6;  
  for(let i=0;i<50;i++){  
    ctx.beginPath();  
    let x=Math.random()*size, y=Math.random()*size;  
    ctx.moveTo(x,y);  
    for(let j=0;j<6;j++){ x+=(Math.random()-0.5)*50; y+=(Math.random()-0.5)*50; ctx.lineTo(x,y); }  
    ctx.stroke();  
  }  
  const g=ctx.createRadialGradient(size/2,size/2,size*0.25,size/2,size/2,size*0.85);  
  g.addColorStop(0,'rgba(0,0,0,0)'); g.addColorStop(1,'rgba(90,80,60,0.12)');  
  ctx.fillStyle=g; ctx.fillRect(0,0,size,size);  
  const albedo = new THREE.CanvasTexture(canvas);  
  albedo.wrapS=albedo.wrapT=THREE.RepeatWrapping;  
  
  const c2=document.createElement('canvas');  
  c2.width=size; c2.height=size; const x2=c2.getContext('2d');  
  x2.fillStyle='#8080ff'; x2.fillRect(0,0,size,size);  
  for(let i=0;i<6000;i++){  
    const x=Math.random()*size, y=Math.random()*size, r=Math.random()*1.5;  
    x2.fillStyle = Math.random()>0.5 ? 'rgba(140,140,255,0.25)' : 'rgba(200,200,255,0.25)';  
    x2.beginPath(); x2.arc(x,y,r,0,Math.PI*2); x2.fill();  
  }  
  const bump = new THREE.CanvasTexture(c2);  
  bump.wrapS=bump.wrapT=THREE.RepeatWrapping;  
  
  const c3=document.createElement('canvas');  
  c3.width=size; c3.height=size; const x3=c3.getContext('2d');  
  x3.fillStyle='#b0b0b0'; x3.fillRect(0,0,size,size);  
  for(let i=0;i<4000;i++){  
    const x=Math.random()*size, y=Math.random()*size, r=Math.random()*2;  
    x3.fillStyle = `rgba(${120+Math.random()*40|0},${120+Math.random()*40|0},${120+Math.random()*40|0},0.3)`;  
    x3.beginPath(); x3.arc(x,y,r,0,Math.PI*2); x3.fill();  
  }  
  const rough = new THREE.CanvasTexture(c3);  
  rough.wrapS=rough.wrapT=THREE.RepeatWrapping;  
  return {albedo,bump,rough};  
}  
  
// Cancellous (spongy) bone texture -- for the specific meshes that
// represent joint-end/articular bone (trochlea, capitulum, humeral
// head, glenoid, dens) rather than shaft. Real bone near a joint
// surface is less densely mineralized and visibly more porous than the
// diaphysis, which the single shared boneMat/boneTex couldn't
// represent since it's used uniformly everywhere. This is a separate,
// additional material -- boneMat itself is completely untouched, so
// nothing that isn't explicitly reassigned below can be affected by it.
function createBoneEndTexture() {  
  const size = 512;  
  const canvas = document.createElement('canvas');  
  canvas.width = size; canvas.height = size;  
  const ctx = canvas.getContext('2d');  
  ctx.fillStyle = '#dcd6cc';  
  ctx.fillRect(0, 0, size, size);  
  for (let i=0; i<14000; i++){  
    const x = Math.random()*size, y = Math.random()*size, r = Math.random()*2.0;  
    const dark = Math.random() > 0.4;  
    ctx.fillStyle = dark ? 'rgba(140,132,118,0.4)' : 'rgba(240,236,226,0.3)';  
    ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.fill();  
  }  
  for (let i=0; i<300; i++){  
    const x = Math.random()*size, y = Math.random()*size, r = 1 + Math.random()*2.5;  
    ctx.fillStyle = 'rgba(120,112,98,0.3)';  
    ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.fill();  
  }  
  const albedo = new THREE.CanvasTexture(canvas);  
  albedo.wrapS = albedo.wrapT = THREE.RepeatWrapping;  
  return albedo;  
}  
  
// Ligament fiber bump texture -- parallel, slightly wavy streaks running
// the full canvas height, so that when wrapped around a TubeGeometry
// (whose V coordinate runs along the tube's length) the fibers read as
// running along the ligament, matching how real collagen fiber bundles
// are oriented along a ligament's tension axis. Ligaments previously
// used a completely flat material while bone had a full procedural
// texture -- this reuses the exact same canvas-texture technique.
function createLigamentTexture() {  
  const size = 512;  
  const canvas = document.createElement('canvas');  
  canvas.width = size; canvas.height = size;  
  const ctx = canvas.getContext('2d');  
  ctx.fillStyle = '#8080ff';  
  ctx.fillRect(0,0,size,size);  
  const streakCount = 90;  
  for (let i=0; i<streakCount; i++){  
    const baseX = (i/streakCount)*size + (Math.random()-0.5)*(size/streakCount)*0.6;  
    const raised = Math.random() > 0.5;  
    ctx.strokeStyle = raised ? 'rgba(150,150,255,0.35)' : 'rgba(110,110,255,0.3)';  
    ctx.lineWidth = 0.8 + Math.random()*1.4;  
    ctx.beginPath();  
    let x = baseX;  
    ctx.moveTo(x, 0);  
    for (let y=0; y<=size; y+=32){  
      x += (Math.random()-0.5)*6;  
      ctx.lineTo(x, y);  
    }  
    ctx.stroke();  
  }  
  const bump = new THREE.CanvasTexture(canvas);  
  bump.wrapS = bump.wrapT = THREE.RepeatWrapping;  
  return bump;  
}  
  
const boneTex = createBoneTextures();  
const boneEndTex = createBoneEndTexture();  
const ligamentTex = createLigamentTexture();  
  
/* ─── MATERIALS ─── */  
const boneMat = new THREE.MeshPhysicalMaterial({  
  map: boneTex.albedo, bumpMap: boneTex.bump, bumpScale: 0.015,  
  roughnessMap: boneTex.rough, roughness: 0.75, metalness: 0.05,  
  clearcoat: 0.25, clearcoatRoughness: 0.6,  
  color: 0xe8e0d5, side: THREE.FrontSide  
});  
  
// Separate material for joint-end/articular bone surfaces only --
// slightly grayer, less glossy (lower clearcoat, higher roughness) than
// the shaft, and using the more visibly porous texture above. Reuses
// boneTex.bump for consistent surface micro-detail rather than
// generating a third bump map.
const boneEndMat = new THREE.MeshPhysicalMaterial({  
  map: boneEndTex, bumpMap: boneTex.bump, bumpScale: 0.02,  
  roughness: 0.85, metalness: 0.03,  
  clearcoat: 0.12, clearcoatRoughness: 0.7,  
  color: 0xdad2c6, side: THREE.FrontSide  
});  
  
const cartilageMat = new THREE.MeshPhysicalMaterial({  
  color: 0xc8e0ec, roughness: 0.15, metalness: 0.0,  
  transmission: 0.55, thickness: 1.2, ior: 1.41,  
  transparent: true, opacity: 0.82, side: THREE.DoubleSide,  
  attenuationColor: new THREE.Color(0xa8c8d8), attenuationDistance: 0.8,  
  clearcoat: 0.6, clearcoatRoughness: 0.08  
});  

// Cartilage's "wet" look comes from a thin glossy surface layer that
// intensifies at grazing angles (fresnel) -- clearcoat above simulates
// that layer, but a clearcoat with nothing to reflect just shows black.
// This generates a small synthetic studio-room environment (no external
// texture, self-contained) once, lazily, the first time a real WebGL
// renderer is available, and wires it into the cartilage-family
// materials. Wrapped defensively: PMREMGenerator needs actual GPU
// rendering capability, so if it ever fails for any reason on a given
// device, cartilage should simply fall back to its previous look
// rather than breaking the joint entirely. Cached with a proper
// success/failure sentinel (not just null) so a failure is remembered
// and doesn't retry on every single joint switch.
let sharedCartilageEnvMap = null;
function ensureCartilageEnvMap(renderer) {  
  if (sharedCartilageEnvMap !== null) return sharedCartilageEnvMap;  
  try {  
    const pmremGenerator = new THREE.PMREMGenerator(renderer);  
    const envScene = new THREE.Scene();  
    const room = new THREE.Mesh(  
      new THREE.BoxGeometry(20, 20, 20),  
      new THREE.MeshBasicMaterial({ side: THREE.BackSide, color: 0x3a3a42 })  
    );  
    envScene.add(room);  
    const topLight = new THREE.Mesh(new THREE.PlaneGeometry(6, 6), new THREE.MeshBasicMaterial({ color: 0xf0f0f5 }));  
    topLight.position.set(0, 9, 0); topLight.rotation.x = Math.PI / 2;  
    envScene.add(topLight);  
    const coolLight = new THREE.Mesh(new THREE.PlaneGeometry(4, 4), new THREE.MeshBasicMaterial({ color: 0xb8ccf0 }));  
    coolLight.position.set(-8, 3, 5); coolLight.lookAt(0, 3, 0);  
    envScene.add(coolLight);  
    const warmLight = new THREE.Mesh(new THREE.PlaneGeometry(3, 3), new THREE.MeshBasicMaterial({ color: 0xf0ddb8 }));  
    warmLight.position.set(7, 2, -5); warmLight.lookAt(0, 3, 0);  
    envScene.add(warmLight);  

    sharedCartilageEnvMap = pmremGenerator.fromScene(envScene, 0.04).texture;  
    pmremGenerator.dispose();  

    [cartilageMat, fluidMat, labrumMat].forEach(mat => {  
      mat.envMap = sharedCartilageEnvMap;  
      mat.envMapIntensity = 0.7;  
      mat.needsUpdate = true;  
    });  
  } catch (e) {  
    sharedCartilageEnvMap = false; // remembered permanent failure -- don't retry every joint switch  
  }  
  return sharedCartilageEnvMap;  
}  

  
const fluidMat = new THREE.MeshPhysicalMaterial({  
  color: 0xc8e4f0, roughness: 0.05, metalness: 0.0,  
  transmission: 0.98, thickness: 0.15, ior: 1.33,  
  transparent: true, opacity: 0.18, side: THREE.DoubleSide,  
  depthWrite: false  
});  
  
const capsuleMat = new THREE.MeshPhysicalMaterial({  
  color: 0xd8c8b8, roughness: 0.9, metalness: 0.0,  
  transparent: true, opacity: 0.14, side: THREE.DoubleSide,  
  depthWrite: false  
});  
  
const synoviumMat = new THREE.MeshPhysicalMaterial({  
  color: 0xe8a8a0, roughness: 0.8, metalness: 0.0,  
  transparent: true, opacity: 0.22, side: THREE.BackSide,  
  depthWrite: false  
});  
  
const ligamentMat = new THREE.MeshPhysicalMaterial({  
  color: 0xc8b8a0, roughness: 0.95, metalness: 0.0,  
  bumpMap: ligamentTex, bumpScale: 0.012,  
  transparent: true, opacity: 0.85  
});  
  
const labrumMat = new THREE.MeshPhysicalMaterial({
  color: 0xb8c8d0, roughness: 0.4, metalness: 0.0,
  transparent: true, opacity: 0.75, side: THREE.DoubleSide
});

/* ─── RIGGED SKELETON LIBRARY (from Skeleton.obj) ───
   Real bone meshes taken from Skeleton.obj. That file is ONE merged
   mesh, so it was split offline into its 114 separate bone islands
   (connected components), and each bone used here was smoothed with
   one Loop-subdivision pass. Embedded below, so no network fetch.

   Stored in the OBJ's own frame: metres, +Y up, +Z anterior,
   +X = the subject's LEFT side, arms in T-pose along +-X.

   OBJ files carry no bones/skin weights, so the RIG is built here:
   each bone mesh is baked into the local frame of a pivot Group placed
   at the anatomical joint centre, and the scene animates the pivot.
   Rigid bones need no skinning, so this is the correct rig for a
   skeleton (one bone = one rigid segment). */
const OBJ_BONE_LIB = {"bp_atlas":{"p":"","s":2e-05,"o":[-0.00057,1.54993,-0.03588],"i":""},"bp_axis":{"p":"","s":2e-05,"o":[-0.00069,1.53387,-0.0384],"i":""},"bp_c3":{"p":"","s":2e-05,"o":[-0.00065,1.50948,-0.03703],"i":""},"bp_disc":{"p":"","s":2e-05,"o":[-0.00068,1.05017,-0.00629],"i":""},"bp_ethmoid":{"p":"","s":2e-05,"o":[-0.00068,1.59293,0.04351],"i":""},"bp_frontal":{"p":"","s":2e-05,"o":[-0.00066,1.65351,0.04205],"i":""},"bp_incisor":{"p":"","s":2e-05,"o":[0.00394,1.54369,0.07691],"i":""},"bp_l3":{"p":"","s":2e-05,"o":[-0.00065,1.06682,-0.02757],"i":""},"bp_l4":{"p":"","s":2e-05,"o":[-0.00068,1.03914,-0.03172],"i":""},"bp_lacrimal_l":{"p":"","s":2e-05,"o":[0.01263,1.59049,0.05775],"i":""},"bp_lacrimal_r":{"p":"","s":2e-05,"o":[-0.01276,1.59273,0.05824],"i":""},"bp_mandible":{"p":"","s":2e-05,"o":[-0.0006,1.54199,0.03181],"i":""},"bp_maxilla_l":{"p":"","s":2e-05,"o":[0.02133,1.57675,0.05485],"i":""},"bp_maxilla_r":{"p":"","s":2e-05,"o":[-0.0239,1.57683,0.0567],"i":""},"bp_nasal_l":{"p":"","s":2e-05,"o":[0.00234,1.59578,0.07938],"i":""},"bp_nasal_r":{"p":"","s":2e-05,"o":[-0.00495,1.59529,0.08021],"i":""},"bp_occipital":{"p":"","s":2e-05,"o":[-0.00059,1.60922,-0.05852],"i":""},"bp_palatine_l":{"p":"","s":2e-05,"o":[0.01296,1.56987,0.02665],"i":""},"bp_palatine_r":{"p":"","s":2e-05,"o":[-0.01428,1.57001,0.02661],"i":""},"bp_parietal_l":{"p":"","s":2e-05,"o":[0.03358,1.6551,-0.04156],"i":""},"bp_parietal_r":{"p":"","s":2e-05,"o":[-0.03568,1.65514,-0.04347],"i":""},"bp_sphenoid":{"p":"","s":2e-05,"o":[-0.00068,1.59184,0.01764],"i":""},"bp_teeth_lower":{"p":"","s":2e-05,"o":[-0.00065,1.52327,0.05242],"i":""},"bp_teeth_upper":{"p":"","s":2e-05,"o":[-0.00063,1.54622,0.05908],"i":""},"bp_temporal_l":{"p":"","s":2e-05,"o":[0.04207,1.59158,-0.01561],"i":""},"bp_temporal_r":{"p":"","s":2e-05,"o":[-0.04334,1.59164,-0.01563],"i":""},"bp_vomer":{"p":"","s":2e-05,"o":[-0.00068,1.57448,0.03827],"i":""},"bp_zygomatic_l":{"p":"","s":2e-05,"o":[0.04757,1.58679,0.04159],"i":""},"bp_zygomatic_r":{"p":"","s":2e-05,"o":[-0.04891,1.58675,0.04161],"i":""},"clavicle":{"p":"","i":""},"femur":{"p":"","i":""},"hand":{"p":"","i":""},"hipbone":{"p":"","i":""},"humerus":{"p":"","i":""},"radius":{"p":"","i":""},"scapula":{"p":"","i":""},"ulna":{"p":"","i":""}};
const _objGeoCache = {};
function objBoneSourceGeometry(name){
  if (_objGeoCache[name]) return _objGeoCache[name];
  const e = OBJ_BONE_LIB[name];
  const dec = s => { const b = atob(s), u = new Uint8Array(b.length); for (let i=0;i<b.length;i++) u[i]=b.charCodeAt(i); return u.buffer; };
  let pos;
  if (e.s){                                         // BodyParts3D bones: int16 steps of e.s metres about centre e.o
    const q = new Int16Array(dec(e.p)); pos = new Float32Array(q.length);
    for (let i=0;i<q.length;i++) pos[i] = q[i]*e.s + e.o[i%3];
  } else {                                          // Skeleton.obj bones: int32 in 0.1 mm units
    const q = new Int32Array(dec(e.p)); pos = new Float32Array(q.length);
    for (let i=0;i<q.length;i++) pos[i] = q[i] / 10000;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setIndex(new THREE.BufferAttribute(new Uint16Array(dec(e.i)), 1));
  _objGeoCache[name] = g;                           // never added to a scene, so disposeCurrent() can't free it
  return g;
}
// Box-projected UVs (the OBJ bones have none) so the shared procedural
// bone textures (albedo/bump/roughness) read the same on these meshes
// as on the hand-built parts. uvScale = texture repeats per scene unit.
function applyBoxUV(g, uvScale){
  const p = g.attributes.position, n = g.attributes.normal;
  const uv = new Float32Array(p.count*2);
  for (let i=0;i<p.count;i++){
    const ax=Math.abs(n.getX(i)), ay=Math.abs(n.getY(i)), az=Math.abs(n.getZ(i));
    let u, v;
    if (ax>=ay && ax>=az){ u=p.getZ(i); v=p.getY(i); }
    else if (ay>=az){ u=p.getX(i); v=p.getZ(i); }
    else { u=p.getX(i); v=p.getY(i); }
    uv[i*2]=u*uvScale; uv[i*2+1]=v*uvScale;
  }
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
}
// Places an OBJ bone into a scene/pivot frame:
//   scene_point = basis * (scale * (obj_point - jointObj)) + jointScene
// so the anatomical point `jointObj` (metres, OBJ frame) lands exactly on
// `jointScene`. For a rigged bone, jointScene is (0,0,0) and the mesh is
// added to a pivot Group sitting at the joint centre.
function objBone(name, mat, {jointObj, jointScene = new THREE.Vector3(), scale, basis}){
  const g = objBoneSourceGeometry(name).clone();
  g.translate(-jointObj.x, -jointObj.y, -jointObj.z);
  g.scale(scale, scale, scale);
  g.applyMatrix4(basis);
  g.translate(jointScene.x, jointScene.y, jointScene.z);
  g.computeVertexNormals();
  applyBoxUV(g, 0.6);
  const m = new THREE.Mesh(g, mat);
  m.castShadow = true; m.receiveShadow = true;
  return m;
}
// Rigid re-seat of a placed bone: rotates it about srcAnchor so the
// direction (srcAnchor -> srcPoint) becomes (dstAnchor -> dstPoint), then
// moves srcAnchor onto dstAnchor. Used to sit an OBJ bone's shaft into a
// hand-built articular end without bending or scaling the bone.
function seatBone(mesh, srcAnchor, dstAnchor, srcPoint, dstPoint){
  const q = new THREE.Quaternion().setFromUnitVectors(
    srcPoint.clone().sub(srcAnchor).normalize(), dstPoint.clone().sub(dstAnchor).normalize());
  const g = mesh.geometry;
  g.translate(-srcAnchor.x, -srcAnchor.y, -srcAnchor.z);
  g.applyQuaternion(q);
  g.translate(dstAnchor.x, dstAnchor.y, dstAnchor.z);
  g.computeVertexNormals();
  applyBoxUV(g, 0.6);
}
// Removes part of a bone (every triangle whose centre fails keepFn) and
// closes each opening with a triangle fan, so the cut end is a solid
// surface rather than a see-through hole. Cuts always sit inside a
// hand-built articular part, so they never show.
function cutBoneAtY(mesh, cutY, keepAbove){
  cutBone(mesh, c => (c.y >= cutY) === keepAbove);
}
function cutBoneSphere(mesh, centre, radius){            // hollows out a ball-shaped region
  // cap centres are pushed out onto the sphere so the caps never dip into it
  cutBone(mesh, c => c.distanceTo(centre) > radius, c => {
    const d = c.clone().sub(centre); if (d.length() < radius) c.copy(centre).addScaledVector(d.normalize(), radius);
  });
}
function cutBone(mesh, keepFn, adjustCap){
  const g = mesh.geometry, p = g.attributes.position, idx = g.index.array;
  const cen = new THREE.Vector3();
  const kept = [], edgeUse = new Map(), allUse = new Map();
  const key = (a,b) => a < b ? a+'_'+b : b+'_'+a;
  for (let t=0; t<idx.length; t+=3){
    const a=idx[t], b=idx[t+1], c=idx[t+2];
    [[a,b],[b,c],[c,a]].forEach(([u,v]) => allUse.set(key(u,v), (allUse.get(key(u,v))||0)+1));
    cen.set((p.getX(a)+p.getX(b)+p.getX(c))/3, (p.getY(a)+p.getY(b)+p.getY(c))/3, (p.getZ(a)+p.getZ(b)+p.getZ(c))/3);
    if (keepFn(cen)){
      kept.push(a,b,c);
      [[a,b],[b,c],[c,a]].forEach(([u,v]) => { const k=key(u,v); edgeUse.set(k, (edgeUse.get(k)||[])); edgeUse.get(k).push([u,v]); });
    }
  }
  // cut edges: used once by kept triangles but twice in the original mesh
  const cutEdges = [];
  edgeUse.forEach((list, k) => { if (list.length === 1 && allUse.get(k) === 2) cutEdges.push(list[0]); });
  // group cut edges into separate openings (connected components)
  const parent = new Map(); const find = x => { while (parent.get(x) !== x){ parent.set(x, parent.get(parent.get(x))); x = parent.get(x); } return x; };
  cutEdges.forEach(([u,v]) => { if(!parent.has(u)) parent.set(u,u); if(!parent.has(v)) parent.set(v,v); parent.set(find(u), find(v)); });
  const loops = new Map();
  cutEdges.forEach(e => { const r = find(e[0]); if(!loops.has(r)) loops.set(r, []); loops.get(r).push(e); });
  const pos = Array.from(p.array);
  loops.forEach(edges => {
    const vs = new Set(); edges.forEach(([u,v]) => { vs.add(u); vs.add(v); });
    let cx=0, cy=0, cz=0; vs.forEach(i => { cx+=p.getX(i); cy+=p.getY(i); cz+=p.getZ(i); });
    const cc = new THREE.Vector3(cx/vs.size, cy/vs.size, cz/vs.size);
    if (adjustCap) adjustCap(cc);
    const ci = pos.length/3; pos.push(cc.x, cc.y, cc.z);
    edges.forEach(([u,v]) => kept.push(v, u, ci));   // reversed winding = faces outward
  });
  // compact: keep only vertices still referenced (so bounds/culling/raycasts
  // reflect the cut bone, not the removed part)
  const remap = new Map(), cpos = [], cidx = [];
  for (const i of kept){
    if (!remap.has(i)){ remap.set(i, cpos.length/3); cpos.push(pos[i*3], pos[i*3+1], pos[i*3+2]); }
    cidx.push(remap.get(i));
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.Float32BufferAttribute(cpos, 3));
  out.setIndex(cidx);
  out.computeVertexNormals();
  applyBoxUV(out, 0.6);
  g.dispose();
  mesh.geometry = out;
}
  
/* ─── SCENE MANAGER ─── */  
let currentScene=null, currentCamera=null, currentRenderer=null, currentControls=null, animId=null, clock=new THREE.Clock();  
const dia = document.getElementById('dia');  
  
// One WebGL context for the whole page lifetime, created lazily on first  
// use and never destroyed until the page itself unloads. Some embedded  
// viewers (e.g. a file opened from a downloads app) allow only a very  
// small number of live WebGL contexts, so creating/destroying a fresh  
// WebGLRenderer on every joint-type click reliably runs out and throws  
// "Error creating WebGL context". Reusing a single renderer sidesteps  
// that limit entirely.  
let sharedRenderer = null;  
function getSharedRenderer(){  
  if(!sharedRenderer){  
    sharedRenderer = new THREE.WebGLRenderer({antialias:true, alpha:false, powerPreference:'high-performance'});  
    sharedRenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));  
    sharedRenderer.toneMapping = THREE.ACESFilmicToneMapping;  
    sharedRenderer.toneMappingExposure = 1.15;  
    sharedRenderer.shadowMap.enabled = true;  
    sharedRenderer.shadowMap.type = THREE.PCFSoftShadowMap;  
    sharedRenderer.localClippingEnabled = true;  
    dia.appendChild(sharedRenderer.domElement);  
  }  
  sharedRenderer.setSize(dia.clientWidth, dia.clientHeight);  
  return sharedRenderer;  
}  
  
function disposeCurrent(){  
  if(animId) cancelAnimationFrame(animId);  
  
  // Free every geometry/material this build created (NOT the shared  
  // boneTex canvas textures, which are reused across builders and must  
  // survive). material.dispose() does not cascade to its map/bumpMap/  
  // roughnessMap textures, so this is safe.  
  if(currentScene){  
    currentScene.traverse(obj=>{  
      // Each scene's lights own shadow-map render targets (2048x2048 for
      // the key light, ~16 MB of GPU memory); without this they were never
      // freed, so every joint switch leaked them until a phone ran out of
      // GPU memory.
      if(obj.isLight && obj.shadow && obj.shadow.map) obj.shadow.dispose();
      if(obj.geometry) obj.geometry.dispose();  
      if(obj.material){  
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];  
        mats.forEach(m=>m.dispose());  
      }  
    });  
  }  
  
  // The renderer/canvas itself is intentionally NOT disposed or removed  
  // here — it's the shared, session-long WebGL context (see  
  // getSharedRenderer above). Only the per-build scene contents go away.  
  //
  // currentControls DOES need disposal here even though the canvas is
  // shared: initBaseScene() creates a brand new OrbitControls on every
  // single joint switch, and OrbitControls attaches its own pointerdown/
  // pointermove/pointerup/wheel/touchstart/contextmenu listeners directly
  // to that shared canvas. Without calling .dispose() (which removes
  // those listeners), every switch between joint types left the previous
  // instance's listeners attached forever -- one extra full set per
  // switch, accumulating for the whole session, each one still firing
  // (just harmlessly driving an orphaned camera that's no longer
  // rendered) on every drag/scroll. Not visually obvious, but a real,
  // compounding performance cost across a long testing session.
  if(currentControls) currentControls.dispose();  
  // Fixed joint's suture-click listeners (see buildFixed) attach directly
  // to this same shared canvas and were never being removed on navigating
  // away -- clean them up here using the references buildFixed stashed on
  // itself, and null them out so this only ever runs once per load.
  if(currentRenderer && buildFixed._onPointerMove){  
    currentRenderer.domElement.removeEventListener('mousemove', buildFixed._onPointerMove);  
    currentRenderer.domElement.removeEventListener('click', buildFixed._onClick);  
    buildFixed._onPointerMove = null;  
    buildFixed._onClick = null;  
  }  
  const infoDiv = dia.querySelector('.controls-info');  
  if(infoDiv) infoDiv.innerHTML = 'Left-click: Rotate &bull; Right-click: Pan &bull; Scroll: Zoom';  
  const existingLoading = dia.querySelector('.loading-overlay');  
  if(existingLoading) existingLoading.remove();  
  dia.querySelectorAll('div').forEach(el=>{  
    if(el.textContent && el.textContent.indexOf('3D render error:')===0) el.remove();  
  });  
  currentScene=null; currentCamera=null; currentControls=null;  
}  
  
function initBaseScene(){  
  const scene = new THREE.Scene();  
  scene.background = new THREE.Color(0x050508);  
  scene.fog = new THREE.FogExp2(0x050508, 0.04);  
  
  const camera = new THREE.PerspectiveCamera(32, dia.clientWidth/dia.clientHeight, 0.1, 100);  
  camera.position.set(4, 3, 6);  
  
  const renderer = getSharedRenderer();  
  ensureCartilageEnvMap(renderer);  
  
  const controls = new OrbitControls(camera, renderer.domElement);  
  controls.enableDamping = true; controls.dampingFactor = 0.08;  
  controls.minDistance = 2; controls.maxDistance = 14;  
  controls.target.set(0,0,0);  
  
  const hemi = new THREE.HemisphereLight(0xd0d8e8, 0x1a1a20, 0.6);  
  scene.add(hemi);  
  
  const key = new THREE.DirectionalLight(0xfff8f0, 2.0);  
  key.position.set(4, 8, 5); key.castShadow = true;  
  key.shadow.mapSize.set(2048,2048); key.shadow.bias = -0.0001;  
  key.shadow.camera.near=1; key.shadow.camera.far=20;  
  key.shadow.camera.left=-6; key.shadow.camera.right=6;  
  key.shadow.camera.top=6; key.shadow.camera.bottom=-6;  
  scene.add(key);  
  
  const fill = new THREE.DirectionalLight(0xc8d8e8, 0.6);  
  fill.position.set(-5, 3, -3); scene.add(fill);  
  
  const rim = new THREE.DirectionalLight(0xffe8d0, 0.8);  
  rim.position.set(-2, 4, -6); scene.add(rim);  
  
  const spot = new THREE.SpotLight(0xffffff, 1.5, 20, Math.PI/6, 0.5, 1);  
  spot.position.set(0, 10, 0); spot.target.position.set(0,0,0);  
  spot.castShadow = true; scene.add(spot); scene.add(spot.target);  
  
  return {scene, camera, renderer, controls};  
}  
  
/* ─── GEOMETRY HELPERS ─── */  
function createLigament(points, radius=0.04, mat=ligamentMat){  
  const curve = new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p)));  
  const g = new THREE.TubeGeometry(curve, 32, radius, 8, false);  
  return new THREE.Mesh(g, mat);  
}  
  
// Real ligaments flare out where they attach to bone -- collagen fibers
// spread to distribute the attachment force over a wider area, so the
// insertion is visibly wider than the ligament's mid-body. TubeGeometry
// only supports a single constant radius, so this adds small flared
// cone caps at each end instead of rebuilding the tube itself. Returns
// both caps as an array to add alongside the main ligament mesh.
// Orientation verified directly against the built geometry (not
// assumed): the cone's wide base lands exactly at the insertion point,
// tapering back toward the ligament body.
function createLigamentFanCaps(points, baseRadius, mat){  
  const p0 = new THREE.Vector3(...points[0]);  
  const p1 = new THREE.Vector3(...points[1]);  
  const pLast = new THREE.Vector3(...points[points.length-1]);  
  const pPrevLast = new THREE.Vector3(...points[points.length-2]);  

  const flareRadius = baseRadius * 1.9;  
  const flareLength = baseRadius * 1.3;  

  function makeFlare(insertionPoint, dirTowardBone){  
    const geo = new THREE.ConeGeometry(flareRadius, flareLength, 10, 1, true);  
    const mesh = new THREE.Mesh(geo, mat);  
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), dirTowardBone.clone().negate());  
    mesh.position.copy(insertionPoint).addScaledVector(dirTowardBone.clone().negate(), flareLength/2);  
    return mesh;  
  }  

  const startDir = p0.clone().sub(p1).normalize();  
  const endDir = pLast.clone().sub(pPrevLast).normalize();  
  return [makeFlare(p0, startDir), makeFlare(pLast, endDir)];  
}  
  
