/* ─── SUTURE DATA ─── */  
const SUTURE_DATA = {  
  coronal: {  
    icn: '&#9724;', ttl: 'Coronal Suture', sub: 'Frontal ↔ Parietal',  
    dsc: 'Connects the frontal bone to the parietal bones. Runs across the top of the skull from side to side.',  
    examples: ['Frontal bone', 'Right parietal bone', 'Left parietal bone'],  
    movement: 'No movement.'  
  },  
  sagittal: {  
    icn: '&#9724;', ttl: 'Sagittal Suture', sub: 'Parietal ↔ Parietal',  
    dsc: 'Connects the two parietal bones along the midline of the skull, from front to back.',  
    examples: ['Right parietal bone', 'Left parietal bone'],  
    movement: 'No movement.'  
  },  
  lambdoid: {  
    icn: '&#9724;', ttl: 'Lambdoid Suture', sub: 'Parietal ↔ Occipital',  
    dsc: 'Connects the parietal bones to the occipital bone at the back of the skull.',  
    examples: ['Parietal bones', 'Occipital bone'],  
    movement: 'No movement.'  
  },  
  squamous: {  
    icn: '&#9724;', ttl: 'Squamous Suture', sub: 'Parietal ↔ Temporal',  
    dsc: 'Connects the parietal bone to the temporal bone on each side of the skull.',  
    examples: ['Parietal bone', 'Temporal bone'],  
    movement: 'No movement.'  
  },  
  gomphosis: {  
    icn: '&#9724;', ttl: 'Gomphosis', sub: 'Tooth ↔ Alveolar Bone',  
    dsc: 'A special fibrous joint that anchors a tooth in its socket using the periodontal ligament.',  
    examples: ['Tooth', 'Periodontal ligament', 'Alveolar bone'],  
    movement: 'No movement.'  
  }  
};  
  
/* ─── 1. FIXED — Interactive 3D Skull ─── */  
function buildFixed(){  
  const {scene, camera, renderer, controls} = initBaseScene();  
  const group = new THREE.Group();  
  scene.add(group);  
  
  // Real skull from BodyParts3D (CC BY 4.0, (c) Database Center for Life
  // Science -- see "About this Simulation"), embedded in this file: no
  // download, works offline. Each bone is a separate mesh, so the sutures
  // are real seams between real bones (coronal = frontal/parietals,
  // sagittal = parietal/parietal, lambdoid = parietals/occipital,
  // squamous = parietal/temporal). 2.2 scene units tall, centred at
  // y=0.15, face toward +Z. The mandible is shown in place but static:
  // the temporomandibular joint is synovial, not a fixed joint.
  const V3 = (x,y,z) => new THREE.Vector3(x,y,z);
  const SKULL_PLACE = {
    jointObj: V3(-0.0007, 1.607, -0.017),   // centre of skull + mandible (metres)
    jointScene: V3(0, 0.15, 0),
    scale: 2.2 / 0.2146,                     // skull + mandible are 214.6 mm tall
    basis: new THREE.Matrix4()
  };
  const SKULL_BONES = ['bp_frontal','bp_parietal_l','bp_parietal_r','bp_temporal_l','bp_temporal_r','bp_occipital',
    'bp_sphenoid','bp_ethmoid','bp_zygomatic_l','bp_zygomatic_r','bp_maxilla_l','bp_maxilla_r','bp_nasal_l','bp_nasal_r',
    'bp_lacrimal_l','bp_lacrimal_r','bp_palatine_l','bp_palatine_r','bp_vomer','bp_mandible',
    'bp_teeth_upper','bp_teeth_lower','bp_incisor'];
  const skullModel = new THREE.Group();
  const skullBone = {};
  SKULL_BONES.forEach(n => { skullBone[n] = objBone(n, boneMat, SKULL_PLACE); skullModel.add(skullBone[n]); });

  (() => {
    skullModel.traverse((child) => {  
      if(child.isMesh) {  
        child.castShadow = true;  
        child.receiveShadow = true;  
        child.material = boneMat.clone();  
        child.material.needsUpdate = true;  
      }  
    });  
    // Enamel is whiter and glossier than bone
    ['bp_teeth_upper','bp_teeth_lower','bp_incisor'].forEach(n => {
      const m = skullBone[n].material; m.color.set(0xf4f1ea); m.roughness = 0.35; m.clearcoat = 0.6;
    });
  
    group.add(skullModel);  

    // Gomphosis = the left upper central incisor in its socket. Its crown
    // is 11.6 mm, its root 15 mm; the root enters the maxilla at the
    // alveolar crest (scene y = -0.515). Tapping it makes both maxillae
    // see-through so the root, ligament and socket can be seen.
    const INCISOR = skullBone['bp_incisor'];
    const ALVEOLAR_Y = -0.515;
    const gomphHit = new THREE.Mesh(  
      new THREE.SphereGeometry(0.10, 16, 16),  
      new THREE.MeshBasicMaterial({visible: false})  
    );  
    gomphHit.position.set(0.04, -0.59, 0.99);   // over the incisor crown  
    gomphHit.userData = {type: 'gomphosis', name: 'Gomphosis'};  
    group.add(gomphHit);  

    // Periodontal ligament and bony socket: thin shells around the ROOT,
    // made from the tooth's own root surface, widened sideways about the
    // root's centre line (the ligament is only ~0.2 mm thick in life;
    // exaggerated here so it can be seen).
    function rootShell(widen, lengthen, mat){
      const m = new THREE.Mesh(INCISOR.geometry.clone(), mat);
      cutBoneAtY(m, ALVEOLAR_Y + 0.012, true);   // starts just inside the bone, so it never shows on the crown
      const g = m.geometry; g.computeBoundingBox();
      const c = g.boundingBox.getCenter(new THREE.Vector3());
      g.translate(-c.x, -c.y, -c.z); g.scale(widen, lengthen, widen); g.translate(c.x, c.y, c.z);
      g.computeVertexNormals();
      return m;
    }
    const gomphPDLMat = new THREE.MeshPhysicalMaterial({  
      color: 0xd8a898, roughness: 0.9, transparent: true, opacity: 0.6,  
      emissive: 0xff6644, emissiveIntensity: 0.0, side: THREE.DoubleSide  
    });  
    const gomphPDL = rootShell(1.22, 1.04, gomphPDLMat);
    group.add(gomphPDL);  
  
    const gomphSocketMat = new THREE.MeshPhysicalMaterial({  
      color: 0xe8d8c8, roughness: 0.8, transparent: true, opacity: 0.35,  
      side: THREE.DoubleSide, emissive: 0xff6644, emissiveIntensity: 0.0, depthWrite: false  
    });  
    const gomphSocket = rootShell(1.55, 1.09, gomphSocketMat);
    group.add(gomphSocket);  
    const maxillae = [skullBone['bp_maxilla_l'], skullBone['bp_maxilla_r']];
  
    // ─── SUTURE LINES (built from SUTURE_PATHS) ───
    // Each suture gets a thin visible line that sits on the bone surface,
    // plus a wide invisible "hit" tube around it so a fingertip can tap it.
    // Both carry userData.type ('coronal', 'sagittal', ...), which matches
    // the keys of SUTURE_DATA, so the info card already knows each one.
    function buildSutureLines(){
      const out = [];
      Object.entries(SUTURE_PATHS).forEach(([type, paths]) => {
        paths.forEach(pts => {
          const curve = new THREE.CatmullRomCurve3(pts.map(p => new THREE.Vector3(...p)));
          const segs = Math.max(24, pts.length*4);
          const line = new THREE.Mesh(new THREE.TubeGeometry(curve, segs, 0.010, 6, false),
            new THREE.MeshStandardMaterial({color: 0x7a5c40, roughness: 0.9, emissive: 0xffaa55, emissiveIntensity: 0.15}));
          line.userData = {type};
          line.raycast = () => {};          // taps go to the wide hit tube instead
          const hit = new THREE.Mesh(new THREE.TubeGeometry(curve, segs, 0.07, 6, false),
            new THREE.MeshBasicMaterial({visible: false}));
          hit.userData = {type, name: SUTURE_DATA[type].ttl};
          group.add(line, hit);
          out.push({type, line, hit});
        });
      });
      return out;
    }
    const sutureLines = buildSutureLines();

    // taps are tested against this list: the tooth plus every suture's hit tube
    const clickableObjects = [gomphHit, ...sutureLines.map(s => s.hit)];  
  
    const raycaster = new THREE.Raycaster();  
    const mouse = new THREE.Vector2();  
    let hoveredObj = null;  
    let selectedType = null;  
  
    const camAnim = {  
      active: false,  
      targetPos: new THREE.Vector3(),  
      targetLook: new THREE.Vector3(),  
      speed: 0.035  
    };  
  
    function updateCard(type) {  
      const info = SUTURE_DATA[type] || DATA.fixed;  
      document.getElementById('ttl').textContent = info.ttl;  
      document.getElementById('sub').textContent = info.sub;  
      document.getElementById('dsc').textContent = info.dsc;  
      document.getElementById('mov').textContent = info.movement;  
      const ul = document.getElementById('exm');  
      ul.innerHTML = '';  
      info.examples.forEach(e => {  
        const li = document.createElement('li');  
        li.textContent = e;  
        ul.appendChild(li);  
      });  
    }  
  
    function highlightSuture(type) {  
      clickableObjects.forEach(obj => {  
        if(obj.material && obj.material.emissive) {  
          obj.material.emissiveIntensity = (obj.userData.type === type) ? 0.6 : 0.22;  
        }  
      });  
      // the tapped suture glows; the others stay faint
      sutureLines.forEach(s => { s.line.material.emissiveIntensity = (s.type === type) ? 1.2 : 0.15; });
      const showRoot = (type === 'gomphosis');
      gomphPDL.material.emissiveIntensity = showRoot ? 0.45 : 0.0;
      gomphSocket.material.emissiveIntensity = showRoot ? 0.35 : 0.0;
      // see-through maxillae while the gomphosis is selected
      maxillae.forEach(m => {
        m.material.transparent = showRoot; m.material.opacity = showRoot ? 0.28 : 1.0;
        m.material.depthWrite = !showRoot; m.material.needsUpdate = true;
      });
    }  
  
    function animateCamera(type) {  
      const targets = {  
        gomphosis: { pos: new THREE.Vector3(0.9, -0.9, 3.2), look: new THREE.Vector3(0.04, -0.48, 0.92) },
        coronal:  { pos: new THREE.Vector3(0, 2.6, 3.1),     look: new THREE.Vector3(0, 0.85, 0.35) },   // from the front, above the brow
        sagittal: { pos: new THREE.Vector3(0.4, 4.2, -0.3),  look: new THREE.Vector3(0, 1.0, -0.3) },    // looking down on the top of the head
        lambdoid: { pos: new THREE.Vector3(0, 1.4, -4.0),    look: new THREE.Vector3(0, 0.45, -0.8) },   // from behind
        squamous: { pos: new THREE.Vector3(4.3, 1.0, 0.2),   look: new THREE.Vector3(0.6, 0.35, -0.05) }  // from the left side  
      };  
      const t = targets[type];  
      if(t) {  
        camAnim.targetPos.copy(t.pos);  
        camAnim.targetLook.copy(t.look);  
        camAnim.active = true;  
      }  
    }  
  
    function onPointerMove(e) {  
      const rect = renderer.domElement.getBoundingClientRect();  
      mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;  
      mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;  
      raycaster.setFromCamera(mouse, camera);  
      const intersects = raycaster.intersectObjects(clickableObjects);  
      if(intersects.length > 0) {  
        renderer.domElement.style.cursor = 'pointer';  
        const obj = intersects[0].object;  
        if(hoveredObj !== obj) {  
          if(hoveredObj && hoveredObj.material && hoveredObj.material.emissive && hoveredObj.userData.type !== selectedType) {  
            hoveredObj.material.emissiveIntensity = 0.0;  
          }  
          hoveredObj = obj;  
          if(obj.material && obj.material.emissive && obj.userData.type !== selectedType) {  
            obj.material.emissiveIntensity = 0.3;  
          }  
        }  
      } else {  
        renderer.domElement.style.cursor = 'grab';  
        if(hoveredObj) {  
          if(hoveredObj.material && hoveredObj.material.emissive && hoveredObj.userData.type !== selectedType) {  
            hoveredObj.material.emissiveIntensity = 0.0;  
          }  
          hoveredObj = null;  
        }  
      }  
    }  
  
    function onClick(e) {  
      const rect = renderer.domElement.getBoundingClientRect();  
      mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;  
      mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;  
      raycaster.setFromCamera(mouse, camera);  
      const intersects = raycaster.intersectObjects(clickableObjects);  
      if(intersects.length > 0) {  
        const obj = intersects[0].object;  
        selectedType = obj.userData.type;  
        highlightSuture(selectedType);  
        updateCard(selectedType);  
        animateCamera(selectedType);  
      } else {  
        selectedType = null;  
        highlightSuture(null);  
        updateCard('fixed');  
        camAnim.targetPos.set(4, 3, 6);  
        camAnim.targetLook.set(0, 0, 0);  
        camAnim.active = true;  
      }  
    }  
  
    renderer.domElement.addEventListener('mousemove', onPointerMove);  
    renderer.domElement.addEventListener('click', onClick);  
  
  
    buildFixed._clickableObjects = clickableObjects;  
    buildFixed._gomphPDL = gomphPDL;  
    buildFixed._gomphSocket = gomphSocket;  
    buildFixed._camAnim = camAnim;  
    buildFixed._selectedType = () => selectedType;  
    buildFixed._hoveredObj = () => hoveredObj;  
    // Stored so disposeCurrent() can remove these on navigating away --
    // without this, they stay attached to the shared canvas forever,
    // and firing them against disposed suture geometry from a totally
    // different joint's view was silently overwriting that joint's
    // info card with skull suture data on every click. See disposeCurrent().
    buildFixed._onPointerMove = onPointerMove;  
    buildFixed._onClick = onClick;  
  
  })();
  
  const infoDiv = dia.querySelector('.controls-info');  
  if(infoDiv) {  
    infoDiv.innerHTML = 'Left-click: Rotate &bull; Right-click: Pan &bull; Scroll: Zoom &nbsp;&nbsp;<span style="color:#8a7a6a">| Tap a suture or the tooth to explore</span>';  
  }  
  
  camera.position.set(4, 3, 6);  
  
  function anim(t) {  
    group.rotation.y = Math.sin(t * 0.12) * 0.06;  
    const ca = buildFixed._camAnim;  
    if(ca && ca.active) {  
      camera.position.lerp(ca.targetPos, ca.speed);  
      controls.target.lerp(ca.targetLook, ca.speed);  
      if(camera.position.distanceTo(ca.targetPos) < 0.08) ca.active = false;  
    }  
    const pulse = Math.sin(t * 1.5) * 0.06 + 0.1;  
    const objs = buildFixed._clickableObjects;  
    const sel = buildFixed._selectedType ? buildFixed._selectedType() : null;  
    const hov = buildFixed._hoveredObj ? buildFixed._hoveredObj() : null;  
    if(objs) {  
      objs.forEach(obj => {  
        if(obj.material && obj.material.emissive && obj.userData.type !== sel && obj !== hov) {  
          obj.material.emissiveIntensity = pulse;  
        }  
      });  
    }  
  }  
  
  return {scene, camera, renderer, controls, anim};  
}  
  
/* ─── 2. SLIGHTLY MOVABLE — Intervertebral disc (L3–L4) ───
   Real lumbar vertebrae L3 and L4 and the disc between them, from
   BodyParts3D (CC BY 4.0, (c) Database Center for Life Science -- see
   "About this Simulation"), at 38 scene units per metre. The segment is
   levelled (turned back 16.7 deg, the lordotic tilt it has in the
   standing skeleton) so the disc lies horizontal. Frame: +X = subject's
   left, +Y up, +Z anterior; origin in the middle of the disc.

   Disc: the real disc mesh, translucent, is the annulus fibrosus; its
   wedge shape (about 6 mm thick in front, 3.5 mm behind) is real
   lumbar anatomy. Nucleus pulposus: a gel ellipsoid sized from the
   disc's measured thickness map so it sits fully inside, just behind
   the disc's centre.

   Rig: L3 rocks forward/back (flexion/extension, ~3 deg each way) on a
   pivot in the nucleus, and the segment gently compresses. The disc
   follows half the tilt and flattens; the nucleus flattens, bulges
   sideways, and drifts BACKWARD in flexion -- what a real nucleus does,
   and why bending forward under load stresses the back of the disc. */
function buildSlightly(){
  const {scene, camera, renderer, controls} = initBaseScene();
  const group = new THREE.Group();
  const V3 = (x,y,z) => new THREE.Vector3(x,y,z);
  const S = 38;
  const PLACE = {jointObj: V3(-0.0005, 1.0500, -0.0075), jointScene: V3(0,0,0), scale: S,
                 basis: new THREE.Matrix4().makeRotationX(THREE.MathUtils.degToRad(-16.7))};

  const NUC_C = V3(0, 0.0015*S, -0.003*S);               // nucleus centre (in the disc's mid-layer)
  const l4 = objBone('bp_l4', boneMat, PLACE);
  group.add(l4);

  // L3 rides on a pivot inside the nucleus
  const l3Pivot = new THREE.Group(); l3Pivot.position.copy(NUC_C); group.add(l3Pivot);
  const l3 = objBone('bp_l3', boneMat, PLACE);
  l3.geometry.translate(-NUC_C.x, -NUC_C.y, -NUC_C.z);
  l3Pivot.add(l3);

  // Disc (annulus fibrosus) -- its own pivot so it can share the tilt and flatten
  const discPivot = new THREE.Group(); discPivot.position.copy(NUC_C); group.add(discPivot);
  const annulusMat = new THREE.MeshPhysicalMaterial({
    color: 0xddd3bf, roughness: 0.8, metalness: 0.0, bumpMap: ligamentTex, bumpScale: 0.01,
    transparent: true, opacity: 0.62, side: THREE.DoubleSide, depthWrite: false
  });
  const disc = objBone('bp_disc', annulusMat, PLACE);
  disc.castShadow = false;
  disc.geometry.translate(-NUC_C.x, -NUC_C.y, -NUC_C.z);
  disc.renderOrder = 2;
  discPivot.add(disc);

  const nucleus = new THREE.Mesh(new THREE.SphereGeometry(1, 40, 24), new THREE.MeshPhysicalMaterial({  
    color: 0x8ab4d4, roughness: 0.1, metalness: 0.0, transmission: 0.65, thickness: 0.5,  
    transparent: true, opacity: 0.75, ior: 1.35  
  }));  
  const NUC_R = V3(0.0090*S, 0.0019*S, 0.0065*S);        // fits inside the measured disc thickness
  nucleus.scale.copy(NUC_R);
  discPivot.add(nucleus);

  scene.add(group);  
  camera.position.set(5.6, 2.6, 5.4);  
  controls.target.set(0, -0.05, -0.45);
  function anim(t){  
    const sw = Math.sin(t*0.9);
    const flex = sw * (sw > 0 ? 0.05 : 0.025);            // + = flexion; extension is smaller -- the facet joints stop it
    const comp = (1 - Math.cos(t*1.8)) * 0.5;            // 0..1 gentle loading
    l3Pivot.rotation.x = flex;
    l3Pivot.position.y = NUC_C.y - comp*0.008;
    discPivot.rotation.x = flex*0.5;
    discPivot.position.y = NUC_C.y - comp*0.004;
    disc.scale.set(1, 1 - comp*0.06, 1);
    nucleus.scale.set(NUC_R.x*(1+comp*0.06), NUC_R.y*(1-comp*0.12), NUC_R.z*(1+comp*0.06));
    nucleus.position.z = -flex*1.2;                       // drifts backward in flexion
  }  
  const VERT_DESC = 'A lumbar vertebra. Its large body carries body weight; the disc joins it to the next vertebra.';
  const DISC_DESC = 'A pad of fibrocartilage between two vertebral bodies: a tough outer ring (annulus fibrosus) around a soft gel core. Absorbs shock and allows slight movement of the spine.';
  const inspectables = [
    {mesh: l3, label:'Lumbar Vertebra (L3)', desc:VERT_DESC},
    {mesh: l4, label:'Lumbar Vertebra (L4)', desc:VERT_DESC},
    {mesh: disc, label:'Intervertebral Disc', desc:DISC_DESC},
    {mesh: nucleus, label:'Nucleus Pulposus', desc:'The soft, gel-like centre of the disc. It flattens under load and shifts as the spine bends, spreading the pressure.'}
  ];
  return {scene, camera, renderer, controls, anim, inspectables};  
}  
  
/* ─── 3. FREELY MOVABLE (SYNOVIAL JOINT) — shown as the SHOULDER ───
   The generic two-bone synovial joint is replaced by a real one: the
   glenohumeral (shoulder) joint, built from Skeleton.obj's left
   scapula, clavicle and humerus. All the synovial-joint parts the old
   scene taught are still here and still labelled: articular cartilage,
   synovial fluid, synovial membrane, joint capsule, ligaments.

   Frame: origin = centre of the humeral head. +X lateral, +Y up,
   +Z anterior (a LEFT shoulder). 27 units per metre, the same scale as
   the hip, at which the OBJ humeral head (~22 mm radius) matches 0.62.

   Anatomy encoded:
   - The glenoid lies MEDIAL to the head and faces laterally (tilted a
     little forward and up, as the scapula sits on the curved back).
     It is a SHALLOW dish covering only part of the head -- unlike the
     deep acetabulum of the hip -- which is why the shoulder is the most
     mobile and least stable joint. (The previous shoulder version had
     the glenoid behind the head facing forward.)
   - The labrum rims the glenoid; the capsule is loose and roomy.
   - Greater tubercle lateral, lesser tubercle anterior; humeral shaft
     axis slightly lateral and anterior to the head centre.
   - Acromion (OBJ) overhangs the head with a subacromial gap.
   OBJ's own glenoid and humeral head are crude, so those regions are
   cut away and replaced by the hand-built joint.

   Rig: humerusPivot at the head centre -- flexion/extension,
   abduction and rotation all turn about that one point. Ligaments are
   rebuilt each frame between the fixed scapula and the moving humerus. */
function buildFreely(){
  const {scene, camera, renderer, controls} = initBaseScene();
  const group = new THREE.Group();
  const V3 = (x,y,z) => new THREE.Vector3(x,y,z);
  const UP = V3(0,1,0);

  const HEAD_R = 0.62;
  const OPEN_DIR = V3(1.0, 0.10, 0.30).normalize();   // glenoid faces lateral, slightly forward/up
  const GH_OBJ = V3(0.193, 1.432, -0.134);             // OBJ left glenohumeral centre (metres)
  const SCAP_PLACE = {jointObj: GH_OBJ, jointScene: V3(0,0,0), scale: 27, basis: new THREE.Matrix4()};
  const HUM_PLACE  = {jointObj: GH_OBJ, jointScene: V3(0,0,0), scale: 27,
                      basis: new THREE.Matrix4().makeRotationZ(-Math.PI/2)};   // T-pose arm lowered to the side

  // ═══ SCAPULA + CLAVICLE (static) ═══
  const scapula = objBone('scapula', boneMat, SCAP_PLACE);
  cutBoneSphere(scapula, V3(0,0,0), 0.80);             // remove the OBJ's crude glenoid region
  // Lifted 0.25 (~9 mm): in the OBJ the clavicle's lateral end passes
  // only ~2 mm above the humeral head; a real shoulder has ~1.5-2 cm
  // there (the supraspinatus runs through it), with the clavicle meeting
  // the acromion above the joint.
  const clavicle = objBone('clavicle', boneMat, {...SCAP_PLACE, jointScene: V3(0, 0.25, 0)});
  group.add(scapula, clavicle);

  // ═══ GLENOID -- shallow dish on a short neck, axis = OPEN_DIR ═══
  const glenProfile = [[0,-1.0],[0.30,-0.98],[0.50,-0.80],[0.66,-0.48],[0.60,-0.40]];
  [54,40,25,10,0].forEach(a => { const r = THREE.MathUtils.degToRad(a); glenProfile.push([0.68*Math.sin(r), -0.68*Math.cos(r)]); });
  const glenMat = boneEndMat.clone(); glenMat.side = THREE.DoubleSide;
  const glenoid = new THREE.Mesh(new THREE.LatheGeometry(glenProfile.map(([r,h]) => new THREE.Vector2(r,h)), 48), glenMat);
  glenoid.quaternion.setFromUnitVectors(UP, OPEN_DIR);
  glenoid.castShadow = true; glenoid.receiveShadow = true;
  const capAround = (r, frac, mat) => {                 // spherical cap about -OPEN_DIR (lining the dish)
    const m = new THREE.Mesh(new THREE.SphereGeometry(r, 48, 16, 0, Math.PI*2, 0, Math.PI*frac), mat);
    m.quaternion.setFromUnitVectors(UP, OPEN_DIR.clone().negate()); return m;
  };
  const glenCart = capAround(0.665, 0.30, cartilageMat);
  const fluid = capAround(0.655, 0.32, fluidMat);       // thin film between the two cartilage layers
  const labrum = new THREE.Mesh(new THREE.TorusGeometry(0.58, 0.055, 14, 64), labrumMat);
  labrum.quaternion.setFromUnitVectors(V3(0,0,1), OPEN_DIR);
  labrum.position.copy(OPEN_DIR).multiplyScalar(-0.38);
  group.add(glenoid, glenCart, fluid, labrum);

  // ═══ HUMERUS (moves) ═══
  const humerusPivot = new THREE.Group();
  group.add(humerusPivot);
  const head = new THREE.Mesh(new THREE.SphereGeometry(HEAD_R, 48, 40), boneEndMat);
  head.castShadow = true;
  const headCart = new THREE.Mesh(new THREE.SphereGeometry(0.645, 48, 40), cartilageMat);
  function blob(r, pos, scl){
    const m = new THREE.Mesh(new THREE.SphereGeometry(r, 32, 24), boneMat);
    m.position.copy(pos); m.scale.set(...scl); m.castShadow = true; return m;
  }
  const SHAFT_X = 0.19, SHAFT_Z = 0.05;                 // shaft axis: a little lateral and anterior to the head centre
  // Proximal metaphysis: tapered sleeve from under the head into the
  // real shaft; wider than the OBJ shaft above y=-1.3 (hides its cut),
  // narrower at its own bottom (buried in the shaft).
  const metaProfile = [[0.27,-2.4],[0.34,-2.0],[0.44,-1.5],[0.52,-1.0],[0.58,-0.5],[0.60,-0.15],[0.48,0.15],[0.0,0.25]]
    .map(([r,y]) => new THREE.Vector2(r,y));
  const metaphysis = new THREE.Mesh(new THREE.LatheGeometry(metaProfile, 40), boneMat);
  metaphysis.position.set(SHAFT_X, 0, SHAFT_Z); metaphysis.scale.set(1, 1, 0.85); metaphysis.castShadow = true;
  const greaterTub = blob(0.30, V3(0.62, -0.05, -0.02), [0.90, 1.30, 1.0]);   // lateral; top just below the head's top
  const lesserTub  = blob(0.18, V3(0.24, -0.30, 0.52), [0.90, 1.20, 0.90]);   // anterior
  const humerusShaft = objBone('humerus', boneMat, HUM_PLACE);
  // re-seat the OBJ shaft so its axis runs vertically at (SHAFT_X, SHAFT_Z)
  seatBone(humerusShaft, V3(-0.05,-2.0,-0.07), V3(SHAFT_X,-2.0,SHAFT_Z),
                         V3(-0.10,-4.5,-0.15), V3(SHAFT_X,-4.5,SHAFT_Z));
  cutBoneAtY(humerusShaft, -1.3, false);
  humerusPivot.add(head, headCart, metaphysis, greaterTub, lesserTub, humerusShaft);

  // ═══ CAPSULE + SYNOVIAL MEMBRANE (static, translucent, loose) ═══
  const capsule = new THREE.Mesh(new THREE.SphereGeometry(1, 64, 48), capsuleMat);
  capsule.position.set(-0.02, -0.22, 0.02);
  capsule.scale.set(0.98, 1.18, 0.98);
  const synovium = new THREE.Mesh(new THREE.SphereGeometry(0.97, 64, 48), synoviumMat);
  synovium.position.copy(capsule.position); synovium.scale.copy(capsule.scale);
  group.add(capsule, synovium);

  // ═══ LIGAMENTS -- rebuilt each frame (scapular end fixed, humeral end moves) ═══
  const LIGS = [
    {fixed: V3(-0.52, 0.48, 0.40), moving: V3(0.55, 0.30, 0.12), r: 0.05, name: 'Coracohumeral Ligament'},   // coracoid base -> greater tubercle
    {fixed: V3(-0.55, 0.15, 0.40), moving: V3(0.18, -0.20, 0.58), r: 0.04, name: 'Glenohumeral Ligament'},    // anterior glenoid rim -> lesser tubercle
    {fixed: V3(-0.52, -0.40, 0.30), moving: V3(0.10, -0.62, 0.45), r: 0.04, name: 'Glenohumeral Ligament'}    // inferior band
  ];
  const _a = V3(0,0,0), _b = V3(0,0,0), _m = V3(0,0,0);
  LIGS.forEach(L => { L.mesh = new THREE.Mesh(new THREE.BufferGeometry(), ligamentMat); group.add(L.mesh); });
  function updateLigaments(){
    humerusPivot.updateMatrix();
    LIGS.forEach(L => {
      _a.copy(L.fixed);
      _b.copy(L.moving).applyMatrix4(humerusPivot.matrix);
      _m.copy(_a).add(_b).multiplyScalar(0.5);
      _m.addScaledVector(_m.clone().normalize(), 0.30);        // bow outward over the head/capsule
      L.mesh.geometry.dispose();
      L.mesh.geometry = new THREE.TubeGeometry(new THREE.CatmullRomCurve3([_a.clone(), _m.clone(), _b.clone()]), 20, L.r, 8, false);
    });
  }
  updateLigaments();

  scene.add(group);
  controls.maxDistance = 22;
  controls.target.set(0.0, -0.2, 0);
  camera.position.set(5.8, 2.6, 7.4);
  function anim(t){
    const phase = t*0.6;
    humerusPivot.rotation.x = -Math.sin(phase)*0.55;              // flexion (+) / extension
    humerusPivot.rotation.z = 0.20 + Math.sin(phase*0.8)*0.20;    // abduction
    humerusPivot.rotation.y = Math.sin(phase*0.6)*0.45;           // medial / lateral rotation
    updateLigaments();
  }
  const HUM_DESC = 'Upper arm bone. Its rounded head sits against the shallow glenoid of the scapula.';
  const CART_DESC = 'Smooth tissue covering the bone ends. Reduces friction and cushions the joint during movement.';
  const inspectables = [
    ...[head, metaphysis, greaterTub, lesserTub, humerusShaft].map(mesh => ({mesh, label:'Humerus', desc:HUM_DESC})),
    {mesh: scapula, label:'Scapula', desc:'Shoulder blade. A flat bone whose glenoid cavity forms the socket of the shoulder joint.'},
    {mesh: clavicle, label:'Clavicle', desc:'Collar bone. A strut joining the scapula to the sternum, holding the shoulder out to the side.'},
    {mesh: glenoid, label:'Glenoid Cavity', desc:'The shallow socket of the scapula. Because it covers only part of the humeral head, the shoulder moves more freely than any other joint.'},
    {mesh: headCart, label:'Articular Cartilage', desc:CART_DESC},
    {mesh: glenCart, label:'Articular Cartilage', desc:CART_DESC},
    {mesh: fluid, label:'Synovial Fluid', desc:'A slippery fluid filling the joint cavity. Reduces friction and nourishes the cartilage.'},
    {mesh: labrum, label:'Glenoid Labrum', desc:'A ring of fibrocartilage around the glenoid rim. Deepens the shallow socket.'},
    {mesh: capsule, label:'Joint Capsule', desc:'A loose fibrous sleeve enclosing the joint. Its looseness allows the shoulder its wide range of movement.'},
    {mesh: synovium, label:'Synovial Membrane', desc:'Inner lining of the joint capsule. Produces the synovial fluid.'},
    ...LIGS.map(L => ({mesh: L.mesh, label: L.name, desc:'Tough fibrous tissue connecting bone to bone. Stabilizes the joint and limits excess movement.'}))
  ];
  return {scene, camera, renderer, controls, anim, inspectables};
}

/* ─── 4. BALL & SOCKET — Hip (Acetabulofemoral) Joint ───
   Rebuilt as the HIP (the shoulder moved to the Freely Movable
   scene). Real bones from Skeleton.obj: the left hip bone and
   the femoral shaft. The OBJ femur has no head or neck (its
   top is a flat block) and its hip bone has no socket, so the joint
   itself is hand-built and the OBJ bones are cut where they meet it.

   Frame: origin = centre of the femoral head. +X lateral, +Y up,
   +Z anterior (a LEFT hip). OBJ placed at 27 scene units per metre --
   the scale at which a real femoral head (~23 mm radius) matches the
   0.62 head used here.

   Anatomy encoded (and different from the shoulder on purpose):
   - DEEP socket: the acetabulum is a full hemisphere, rimmed by the
     labrum, so it holds most of the head (the glenoid holds only a
     small fraction) -- the bony basis of the hip's stability.
   - Acetabulum faces lateral, ~45 deg downward and ~20 deg forward.
   - Femoral neck runs from head to shaft at ~125 deg to the shaft
     (neck-shaft angle), with ~12 deg anteversion (head points slightly
     forward). Greater trochanter tip at the level of the head centre.
   - The OBJ femoral shaft keeps its own natural medial slope toward the
     knee (anatomical axis), so it is NOT straightened.

   Rig: femurPivot sits at the head centre; flexion/extension,
   abduction/adduction and rotation are all rotations of that one pivot
   -- three axes through one point is what makes it a ball-and-socket.
   Ligaments are rebuilt every frame between their fixed pelvic
   attachment and their moving femoral attachment, so they stretch and
   slacken with the movement instead of detaching. */
function buildBallSocket(){
  const {scene, camera, renderer, controls} = initBaseScene();
  const group = new THREE.Group();
  const V3 = (x,y,z) => new THREE.Vector3(x,y,z);
  const UP = V3(0,1,0);

  const HEAD_R = 0.62;
  const OPEN_DIR = V3(1.0, -0.70, 0.35).normalize();   // where the socket opens to
  const CUP_IN = 0.68, CUP_OUT = 1.0;
  const HIP_PLACE = {
    jointObj: V3(0.085, 0.893, -0.095),                // OBJ left hip joint centre (metres)
    jointScene: V3(0,0,0), scale: 27, basis: new THREE.Matrix4()
  };

  // ═══ PELVIS (static) ═══
  const hipBone = objBone('hipbone', boneMat, HIP_PLACE);
  cutBoneSphere(hipBone, V3(0,0,0), CUP_OUT - 0.04);   // carve out room for the acetabulum
  group.add(hipBone);

  // ═══ ACETABULUM -- deep hemispherical cup ═══
  const cupQ = new THREE.Quaternion().setFromUnitVectors(UP, OPEN_DIR.clone().negate());
  const hemi = r => new THREE.SphereGeometry(r, 56, 28, 0, Math.PI*2, 0, Math.PI/2);
  const acetabInnerMat = boneEndMat.clone(); acetabInnerMat.side = THREE.BackSide;  // concave face
  const acetabInner = new THREE.Mesh(hemi(CUP_IN), acetabInnerMat);
  const acetabOuter = new THREE.Mesh(hemi(CUP_OUT), boneMat);
  [acetabInner, acetabOuter].forEach(m => { m.quaternion.copy(cupQ); m.castShadow = true; m.receiveShadow = true; });
  const rimQ = new THREE.Quaternion().setFromUnitVectors(V3(0,0,1), OPEN_DIR);
  const acetabRim = new THREE.Mesh(new THREE.RingGeometry(CUP_IN, CUP_OUT, 64), boneMat.clone());
  acetabRim.material.side = THREE.DoubleSide;
  acetabRim.quaternion.copy(rimQ);
  const socketCart = new THREE.Mesh(hemi(0.665), cartilageMat);
  socketCart.quaternion.copy(cupQ);
  // Labrum: fibrocartilage ring on the rim, deepening the socket further
  const labrum = new THREE.Mesh(new THREE.TorusGeometry(0.84, 0.085, 16, 72), labrumMat);
  labrum.quaternion.copy(rimQ);
  labrum.position.copy(OPEN_DIR).multiplyScalar(0.05);
  group.add(acetabInner, acetabOuter, acetabRim, socketCart, labrum);

  // ═══ FEMUR (moves) ═══
  const femurPivot = new THREE.Group();
  group.add(femurPivot);
  const NECK_DIR = V3(0.807, -0.568, -0.148).normalize(); // 125 deg neck-shaft angle, ~12 deg anteversion
  const head = new THREE.Mesh(new THREE.SphereGeometry(HEAD_R, 48, 40), boneEndMat);
  head.castShadow = true;
  const headCart = new THREE.Mesh(new THREE.SphereGeometry(0.645, 48, 40), cartilageMat);
  function along(dir, from, to, r0, r1, mat){             // tapered cylinder between two distances along dir
    const m = new THREE.Mesh(new THREE.CylinderGeometry(r1, r0, to-from, 32), mat);
    m.quaternion.setFromUnitVectors(UP, dir.clone().negate());
    m.position.copy(dir).multiplyScalar((from+to)/2);
    m.castShadow = true; return m;
  }
  const neck = along(NECK_DIR, 0.35, 1.75, 0.34, 0.46, boneMat);
  function blob(r, pos, scl){
    const m = new THREE.Mesh(new THREE.SphereGeometry(r, 32, 24), boneMat);
    m.position.copy(pos); m.scale.set(...scl); m.castShadow = true; return m;
  }
  // Intertrochanteric region: one tapered lathe from the neck base down
  // into the real shaft, on the OBJ shaft's own centre line (measured by
  // slicing the mesh: centre (1.10,-0.37) at y=-2.0, sloping medially
  // toward the knee) and slightly flattened front-to-back like the real
  // bone. Widths follow the measured shaft cross-sections: wider than
  // the shaft above y=-2.9 (covering the shaft's cut end), narrower
  // below y=-3.3 (so the sleeve's lower end is buried inside the shaft).
  const SHAFT_TOP = V3(1.10, -2.0, -0.37);
  const SHAFT_DIR = V3(-0.21, -2.8, 0.01).normalize();
  const trochProfile = [[0.30,-3.75],[0.34,-3.6],[0.40,-3.3],[0.50,-2.9],[0.60,-2.45],[0.66,-2.0],[0.66,-1.4],[0.54,-0.95],[0.30,-0.70],[0.0,-0.62]]
    .map(([r,y]) => new THREE.Vector2(r, y - SHAFT_TOP.y));
  const trochMass = new THREE.Mesh(new THREE.LatheGeometry(trochProfile, 40), boneMat);
  trochMass.position.copy(SHAFT_TOP);
  trochMass.quaternion.setFromUnitVectors(V3(0,-1,0), SHAFT_DIR);
  trochMass.scale.set(1, 1, 0.88); trochMass.castShadow = true;
  const greaterTroch = blob(0.40, V3(1.55, -0.60, -0.40), [0.80, 1.20, 0.90]);  // tip at about head-centre level
  const lesserTroch  = blob(0.22, V3(0.62, -2.30, -0.62), [1.0, 1.30, 1.0]);    // posteromedial
  // OBJ femoral shaft: crude top block removed, cut end capped inside trochMass
  const femurShaft = objBone('femur', boneMat, HIP_PLACE);
  cutBoneAtY(femurShaft, -2.5, false);
  femurPivot.add(head, headCart, neck, trochMass, greaterTroch, lesserTroch, femurShaft);

  // ═══ CAPSULE (static, translucent) -- acetabular rim to intertrochanteric line ═══
  const capsule = new THREE.Mesh(new THREE.SphereGeometry(1, 64, 48), capsuleMat);
  capsule.position.copy(NECK_DIR).multiplyScalar(0.70);
  capsule.quaternion.setFromUnitVectors(UP, NECK_DIR);
  capsule.scale.set(1.12, 1.30, 1.12);
  const synovium = new THREE.Mesh(new THREE.SphereGeometry(0.97, 64, 48), synoviumMat);
  synovium.position.copy(capsule.position); synovium.quaternion.copy(capsule.quaternion); synovium.scale.copy(capsule.scale);
  group.add(capsule, synovium);

  // ═══ LIGAMENTS -- rebuilt each frame (pelvic end fixed, femoral end moves) ═══
  const LIGS = [
    // iliofemoral (Y ligament): two limbs from the anterior inferior iliac spine region
    {pelvic: V3(0.55, 1.05, 0.72), femoral: V3(1.10, -1.55, 0.42), r: 0.06, name: 'Iliofemoral Ligament'},
    {pelvic: V3(0.55, 1.05, 0.72), femoral: V3(1.62, -0.85, 0.30), r: 0.055, name: 'Iliofemoral Ligament'},
    // pubofemoral (front-below) and ischiofemoral (behind)
    {pelvic: V3(-0.05, -0.80, 0.80), femoral: V3(0.95, -1.95, 0.30), r: 0.045, name: 'Pubofemoral Ligament'},
    {pelvic: V3(0.05, -0.85, -0.90), femoral: V3(1.62, -0.70, -0.62), r: 0.05, name: 'Ischiofemoral Ligament'}
  ];
  const _a = V3(0,0,0), _b = V3(0,0,0), _m = V3(0,0,0);
  LIGS.forEach(L => { L.mesh = new THREE.Mesh(new THREE.BufferGeometry(), ligamentMat); group.add(L.mesh); });
  function updateLigaments(){
    femurPivot.updateMatrix();
    LIGS.forEach(L => {
      _a.copy(L.pelvic);
      _b.copy(L.femoral).applyMatrix4(femurPivot.matrix);
      _m.copy(_a).add(_b).multiplyScalar(0.5);
      _m.addScaledVector(_m.clone().normalize(), 0.38);        // bow outward so it lies over the capsule
      L.mesh.geometry.dispose();
      L.mesh.geometry = new THREE.TubeGeometry(new THREE.CatmullRomCurve3([_a.clone(), _m.clone(), _b.clone()]), 20, L.r, 8, false);
    });
  }
  updateLigaments();

  scene.add(group);
  controls.maxDistance = 22;            // allow zooming out to see the whole pelvis and femur
  controls.target.set(0.5, -0.5, 0);
  camera.position.set(7.6, 2.8, 8.2);
  function anim(t){
    const phase = t*0.6;
    femurPivot.rotation.x = -Math.sin(phase)*0.40;          // flexion (+) / extension
    femurPivot.rotation.z = Math.sin(phase*0.8)*0.22;       // abduction (+) / adduction
    femurPivot.rotation.y = Math.sin(phase*0.6)*0.30;       // medial / lateral rotation
    updateLigaments();
  }
  const FEMUR_DESC = 'Thigh bone, the longest bone in the body. Its rounded head fits deep into the acetabulum of the hip bone.';
  const HIP_DESC = 'Formed by three fused bones (ilium, ischium, pubis). Its cup-shaped acetabulum is the socket of the hip joint.';
  const ACET_DESC = 'The deep, cup-shaped socket of the hip bone. Because it holds most of the femoral head, the hip is very stable, though less mobile than the shoulder.';
  const CART_DESC = 'Smooth tissue covering the joint surfaces. Reduces friction during movement.';
  const inspectables = [
    ...[head, neck, trochMass, greaterTroch, lesserTroch, femurShaft].map(mesh => ({mesh, label:'Femur', desc:FEMUR_DESC})),
    {mesh: hipBone, label:'Hip Bone (Pelvis)', desc:HIP_DESC},
    {mesh: acetabOuter, label:'Hip Bone (Pelvis)', desc:HIP_DESC},
    {mesh: acetabInner, label:'Acetabulum', desc:ACET_DESC},
    {mesh: acetabRim, label:'Acetabulum', desc:ACET_DESC},
    {mesh: headCart, label:'Articular Cartilage', desc:CART_DESC},
    {mesh: socketCart, label:'Articular Cartilage', desc:CART_DESC},
    {mesh: labrum, label:'Acetabular Labrum', desc:'A ring of fibrocartilage on the rim of the socket. Deepens the socket and grips the femoral head.'},
    {mesh: capsule, label:'Joint Capsule', desc:'A strong fibrous sleeve enclosing the hip joint, lined by synovial membrane.'},
    ...LIGS.map(L => ({mesh: L.mesh, label: L.name, desc: L.name === 'Iliofemoral Ligament'
      ? 'Y-shaped band in front of the hip, one of the strongest ligaments in the body. Stops the hip over-extending.'
      : 'Tough fibrous band connecting the hip bone to the femur. Stabilizes the joint and limits excess movement.'}))
  ];
  return {scene, camera, renderer, controls, anim, inspectables};
}

/* ─── 5. HINGE — Anatomically Accurate Elbow ─── */  
function buildHinge(){  
  const {scene, camera, renderer, controls} = initBaseScene();  
  const group = new THREE.Group();  
  
  const ivoryMat = new THREE.MeshPhysicalMaterial({  
    map: boneTex.albedo, bumpMap: boneTex.bump, bumpScale: 0.02,  
    roughnessMap: boneTex.rough, roughness: 0.68, metalness: 0.03,  
    clearcoat: 0.15, clearcoatRoughness: 0.6,  
    color: 0xede6da, side: THREE.FrontSide  
  });  
  
  const cartMat = new THREE.MeshPhysicalMaterial({  
    color: 0xc8e0ec, roughness: 0.12, metalness: 0.0,  
    transmission: 0.45, thickness: 0.6, ior: 1.41,  
    transparent: true, opacity: 0.72, side: THREE.DoubleSide,  
    clearcoat: 0.55, clearcoatRoughness: 0.08,  
    envMap: sharedCartilageEnvMap || null, envMapIntensity: 0.7  
  });  
  
  const ligMat = new THREE.MeshPhysicalMaterial({  
    color: 0xeef2f5, roughness: 0.8, metalness: 0.0,  
    bumpMap: ligamentTex, bumpScale: 0.01,  
    transparent: true, opacity: 0.88, side: THREE.DoubleSide  
  });  

  
  // ═══════════════════════════════════════════════════════════════  
  //  DISTAL HUMERUS with natural bumps and articulating grooves  
  // ═══════════════════════════════════════════════════════════════  
  const humerusGroup = new THREE.Group();  
  
  // Shaft + distal flare, as ONE continuous surface — profile measured
  // directly from the reference photo (671.jpg) by sampling the bone
  // silhouette's width at each row and converting pixels to world units
  // (calibrated against the trochlea/capitulum edges already in this
  // model). The centerline sits at x=0.18 (not 0) because the photo's
  // shaft is genuinely offset toward the capitulum/lateral side relative
  // to the trochlea — measured, not a mistake. Anteroposterior flattening
  // (z-scale 0.42, ~2.4:1) came from measuring two lateral references
  // (1137.jpg, 1138.jpg): traced the shaft's own width there as a
  // round-shaft calibration check, then the condyle's unobstructed
  // posterior edge for its AP bulge.
  //
  // IMPORTANT correction from the first version: the photo measurement
  // is of the TOTAL visible width at each row — which in the real bone
  // is the combined contribution of the flare AND the trochlea/capitulum
  // protruding from it, not the flare alone. Building the flare to match
  // that total on its own made it re-claim the same space the trochlea
  // and capitulum meshes already occupy, burying 70-90% of both (and
  // leaving the ulna's notch nowhere to sit — the disconnected "U" shape
  // from before). The condyle band below is now sized for the flare's
  // OWN contribution only, letting the trochlea/capitulum genuinely
  // protrude out to the photo-matched total width instead of the flare
  // re-matching it independently. Validated by sampling the trochlea and
  // capitulum meshes' own vertices against this profile: clipping fell
  // from 72%/88% to 15%/34%, both with shallow max depth (~0.17) — a
  // normal base-blends-into-parent overlap, not a burial.
  // Lower profile narrowed (~29% at the peak) from its original values so
  // the shaft visually tapers into a neck before the separately-built
  // trochlea/capitulum lobes take over -- the original width made this a
  // LatheGeometry (radially symmetric, so it can only ever be a single
  // round blob from any angle) wide enough to visually swallow the more
  // detailed articular meshes sitting just past its end, reading as one
  // undifferentiated ball rather than a shaft narrowing into two visible
  // condyle lobes. Top connection point (0.120,-0.007) is unchanged so
  // the shaft above the joint is undisturbed. Re-validated trochlea/
  // capitulum/notch clip percentages against this narrower profile
  // before applying it -- all stayed in the same range already
  // established as acceptable for the previous (wider) profile.
  const humerusProfile = [
    new THREE.Vector2(0.130, -0.700),
    new THREE.Vector2(0.133, -0.646),
    new THREE.Vector2(0.137, -0.597),
    new THREE.Vector2(0.140, -0.548),
    new THREE.Vector2(0.143, -0.499),
    new THREE.Vector2(0.145, -0.450),
    new THREE.Vector2(0.145, -0.400),
    new THREE.Vector2(0.140, -0.351),
    new THREE.Vector2(0.134, -0.302),
    new THREE.Vector2(0.127, -0.253),
    new THREE.Vector2(0.120, -0.204),
    new THREE.Vector2(0.115, -0.154),
    new THREE.Vector2(0.112, -0.105),
    new THREE.Vector2(0.115, -0.056),
    new THREE.Vector2(0.120, -0.007),
    new THREE.Vector2(0.108, 0.190)     // ends here: the real (OBJ) humerus shaft takes over above, overlapping this top section
  ];
  const humerusLatheGeo = new THREE.LatheGeometry(humerusProfile, 40);
  const humerusBody = new THREE.Mesh(humerusLatheGeo, ivoryMat);
  humerusBody.position.set(0.18, 0, 0);
  humerusBody.scale.set(1, 1, 0.42);
  humerusBody.castShadow = true;
  humerusGroup.add(humerusBody);

  // (The old top cap is gone: this lathe now ends at y=0.19, inside the
  // real humerus shaft from Skeleton.obj, so its open rim is never seen.)

  // Medial epicondyle — prominent medial bump. Repositioned to touch
  // the now-narrower flare (was -0.32, calibrated for the old, much
  // thicker condyle band); re-validated to overlap by ~0.02 at its base.
  const medEpiGeo = new THREE.SphereGeometry(0.16, 20, 20);
  const medEpi = new THREE.Mesh(medEpiGeo, ivoryMat);
  medEpi.position.set(-0.155, -0.55, 0.0);
  medEpi.scale.set(1.0, 1.6, 0.85);
  medEpi.castShadow = true;
  humerusGroup.add(medEpi);
  
  // Lateral epicondyle — prominent lateral bump  
  const latEpiGeo = new THREE.SphereGeometry(0.14, 20, 20);  
  const latEpi = new THREE.Mesh(latEpiGeo, ivoryMat);  
  latEpi.position.set(0.38, -0.55, 0.0);  
  latEpi.scale.set(1.0, 1.4, 0.85);  
  latEpi.castShadow = true;  
  humerusGroup.add(latEpi);  
  
  // ─── TROCHLEA — true hourglass/spool profile with a deep central  
  //      groove, built as a solid of revolution so the medial flange,  
  //      groove floor and lateral flange read as one continuous,  
  //      anatomically correct surface (not stacked primitives). ───  
  const trochleaGroup = new THREE.Group();  
  
  const trochProfile = [  
    new THREE.Vector2(0.130, 0.00),   // lateral rim (smaller flange, toward capitulum)  
    new THREE.Vector2(0.138, 0.03),  
    new THREE.Vector2(0.122, 0.09),  
    new THREE.Vector2(0.096, 0.15),  
    new THREE.Vector2(0.088, 0.17),   // groove floor (narrowest point)  
    new THREE.Vector2(0.098, 0.19),  
    new THREE.Vector2(0.128, 0.25),  
    new THREE.Vector2(0.148, 0.30),  
    new THREE.Vector2(0.150, 0.34)    // medial rim (larger flange) -- real anatomy: the  
                                       // medial flange projects further than the lateral  
                                       // one, contributing to the forearm's carrying angle.  
                                       // This was previously backwards (verified directly  
                                       // against the built geometry's world-space radii,  
                                       // not just the profile array) -- the world_x mapping  
                                       // for this lathe runs opposite to what a naive read  
                                       // of the y-values would suggest, so the original  
                                       // profile had medial and lateral swapped even though  
                                       // its own comments described the correct anatomy.  
  ];  
  const trochGeo = new THREE.LatheGeometry(trochProfile, 40);  
  trochGeo.translate(0, -0.17, 0); // center the spool on its own axis  
  const trochlea = new THREE.Mesh(trochGeo, boneEndMat);  
  trochlea.rotation.z = Math.PI / 2; // lay the spool along the mediolateral axis  
  trochlea.castShadow = true;  
  trochleaGroup.add(trochlea);  
  
  // Thin cartilage sheath following the same spool contour, offset  
  // outward slightly so it reads as a distinct articular surface.  
  const trochCartProfile = trochProfile.map(p => new THREE.Vector2(p.x + 0.014, p.y));  
  const trochCartGeo = new THREE.LatheGeometry(trochCartProfile, 40);  
  trochCartGeo.translate(0, -0.17, 0);  
  const trochCart = new THREE.Mesh(trochCartGeo, cartMat);  
  trochCart.rotation.z = Math.PI / 2;  
  trochleaGroup.add(trochCart);  
  
  trochleaGroup.position.set(0, -0.72, 0.04);  
  humerusGroup.add(trochleaGroup);  
  
  // ─── CAPITULUM — rounded knob for radial head ───  
  const capGroup = new THREE.Group();  
  
  // Capitulum — refined from a full sphere to a hemisphere. The real
  // capitulum only articulates anteriorly/inferiorly (with the radial
  // head through its full flexion arc); posteriorly it isn't a rounded
  // surface at all, it's flat and continuous with the lateral condyle.
  // A full sphere therefore overstated the bone by an entire non-existent
  // posterior half. The flat cut face sits at local z<=0 (posterior),
  // embedded in the flare where it's never visible, so nothing about the
  // exposed silhouette changes -- only the previously-hidden geometry is
  // now correct instead of ballooning out unrealistically inside the bone.
  const capGeo = new THREE.SphereGeometry(0.16, 24, 24, 0, Math.PI, 0, Math.PI);  
  const capitulumMat = new THREE.MeshPhysicalMaterial({  
    map: boneEndTex, bumpMap: boneTex.bump, bumpScale: 0.02,  
    roughness: 0.82, metalness: 0.03,  
    clearcoat: 0.16, clearcoatRoughness: 0.65,  
    color: 0xe8dcc8, side: THREE.FrontSide  
  });  
  const capitulum = new THREE.Mesh(capGeo, capitulumMat);  
  capitulum.scale.set(1.0, 0.85, 0.9);  
  capitulum.castShadow = true;  
  capGroup.add(capitulum);  
  
  const capCartGeo = new THREE.SphereGeometry(0.175, 24, 24, 0, Math.PI, 0, Math.PI);  
  const capCart = new THREE.Mesh(capCartGeo, cartMat);  
  capCart.scale.set(1.0, 0.87, 0.92);  
  capGroup.add(capCart);  

  // Visible groove between trochlea and capitulum -- the single biggest
  // lever for breaking up the "one continuous blob" silhouette, since
  // the color/gap changes alone were too subtle at normal viewing scale
  // (verified by direct before/after pixel comparison, not assumed).
  // Positioned in local humerusGroup space, roughly midway between
  // trochlea's lateral rim and capitulum's medial edge.
  const condyleGroove = new THREE.Mesh(
    new THREE.SphereGeometry(0.10, 16, 20),
    new THREE.MeshBasicMaterial({
      color: 0xb3b3b3, transparent: true, opacity: 0.30,  // MultiplyBlending ignores opacity: the colour sets the darkening (black rendered a solid black hole)
      blending: THREE.MultiplyBlending, side: THREE.DoubleSide, depthWrite: false
    })
  );
  condyleGroove.scale.set(0.4, 1.3, 0.55);
  condyleGroove.position.set(0.255, -0.70, 0.05);
  condyleGroove.raycast = () => {}; // decorative only -- must not intercept Inspect Mode clicks meant for the labeled Trochlea/Capitulum meshes it sits between
  humerusGroup.add(condyleGroove);
  
  // Centred ON the flexion axis (y=-0.72, same as the trochlea), not 0.04
  // above it: trochlea and capitulum share one transverse axis in the
  // real elbow, and that is what lets the radial head glide around the
  // capitulum at a constant distance through the whole flexion arc.
  capGroup.position.set(0.50, -0.72, 0.04);
  humerusGroup.add(capGroup);  
  
  // Note: the old supracondylar ridge tubes were removed here — they
  // were shaped to hug the previous (thicker, centered) shaft, and the
  // reference photo doesn't show them as a separate raised feature
  // anyway; the new lathe body already carries that part of the silhouette.

  // Note: the olecranon/coronoid fossae that used to sit here are gone.
  // They existed to carve clearance for those processes against a flare
  // that was much thicker than it should've been (see humerusProfile
  // comment above). With the corrected, narrower profile, the olecranon
  // clips it with zero overlap on its own, and the coronoid needed only
  // a ~0.08-unit nudge (see coronoid.position below) — both re-validated
  // the same way (sampling every surface vertex against the actual
  // profile), so the carved-socket approach is no longer necessary here.

  group.add(humerusGroup);  
  
  // ═══════════════════════════════════════════════════════════════  
  //  FOREARM PIVOT  
  // ═══════════════════════════════════════════════════════════════  
  const HINGE_AXIS = new THREE.Vector3(0, -0.72, 0.04);  
  const forearmPivot = new THREE.Group();  
  forearmPivot.position.copy(HINGE_AXIS);  
  group.add(forearmPivot);  
  
  // ═══════════════════════════════════════════════════════════════  
  //  PROXIMAL ULNA — trochlear notch built as a concave, grooved  
  //  crescent (a real "cup" cross-section swept along the C-shaped  
  //  notch path) so it visibly cradles and locks onto the trochlea  
  //  spool, instead of a plain round tube sitting beside it.  
  // ═══════════════════════════════════════════════════════════════  
  const ulnaGroup = new THREE.Group();  
  
  // Olecranon — refined from a single smooth ellipsoid into a two-lobe
  // hook, matching the real bone's curved beak shape (it's what locks
  // the elbow at full extension by seating in the olecranon fossa) --
  // a plain ball doesn't have that curvature at all. The tip's
  // position was solved numerically, not guessed: swept a set of
  // candidate offsets and picked one with zero clipping against the
  // humerus flare (same validation method used throughout this model),
  // while close enough to the base to blend rather than float
  // separately (0.209 apart vs both lobes' combined reach of 0.26).
  const olecranonGeo = new THREE.SphereGeometry(0.20, 24, 24);  
  const olecranon = new THREE.Mesh(olecranonGeo, ivoryMat);  
  olecranon.position.set(0, -0.65, -0.226);  
  olecranon.scale.set(1.1, 1.6, 0.85);  
  olecranon.castShadow = true;  
  ulnaGroup.add(olecranon);  

  // Two additional segments curving anteriorly (+Z, toward the
  // trochlea) as they rise toward the tip -- turns the olecranon into
  // a genuine curved hook instead of jumping straight from the base
  // blob to the tip blob. Validated: zero clipping against the humerus
  // flare, and solid overlap with both neighbors (0.29 and 0.23 units
  // of overlap respectively, well clear of any gap).
  const olecranonMid1 = new THREE.Mesh(new THREE.SphereGeometry(0.165, 20, 18), ivoryMat);
  olecranonMid1.position.set(0, -0.575, -0.205);
  olecranonMid1.scale.set(1.05, 1.3, 0.9);
  olecranonMid1.castShadow = true;
  ulnaGroup.add(olecranonMid1);

  const olecranonMid2 = new THREE.Mesh(new THREE.SphereGeometry(0.135, 18, 16), ivoryMat);
  olecranonMid2.position.set(0, -0.505, -0.178);
  olecranonMid2.scale.set(1.0, 1.1, 0.9);
  olecranonMid2.castShadow = true;
  ulnaGroup.add(olecranonMid2);

  const olecranonTipGeo = new THREE.SphereGeometry(0.11, 20, 16);
  const olecranonTip = new THREE.Mesh(olecranonTipGeo, ivoryMat);
  olecranonTip.position.set(0, -0.46, -0.156);
  olecranonTip.scale.set(1.0, 1.0, 0.9);
  olecranonTip.castShadow = true;
  ulnaGroup.add(olecranonTip);

  // Articular cartilage on the tip -- this process had none at all
  // before, despite its anterior face being where it approaches the
  // trochlea at full extension.
  const olecranonCartGeo = new THREE.SphereGeometry(0.12, 20, 16, 0, Math.PI, 0, Math.PI);
  const olecranonCart = new THREE.Mesh(olecranonCartGeo, cartMat);
  olecranonCart.position.copy(olecranonTip.position);
  olecranonCart.scale.set(1.0, 1.0, 0.9);
  ulnaGroup.add(olecranonCart);
  
  // Coronoid process — anterior hook that fits into coronoid fossa  
  const coronoidGeo = new THREE.SphereGeometry(0.14, 20, 20);  
  const coronoid = new THREE.Mesh(coronoidGeo, ivoryMat);  
  coronoid.position.set(0, -0.52, 0.22);  
  coronoid.scale.set(1.0, 0.9, 1.2);  
  coronoid.castShadow = true;  
  ulnaGroup.add(coronoid);  
  
  // Trochlear notch — rebuilt as a PARTIAL REVOLVE (LatheGeometry with
  // phiStart/phiLength) using the trochlea's own radius-by-position
  // profile plus a fixed clearance, instead of extruding a fixed
  // cross-section along a curve. The previous approach relied on
  // ExtrudeGeometry's automatically-computed Frenet frame to keep the
  // cup's concave face pointed at the trochlea -- that frame's exact
  // orientation isn't something you can reliably predict or control,
  // and it turned out to be wrong: the notch was overlapping the
  // trochlea by ~22% even though the curve's own centerline looked
  // properly offset. This construction can't have that failure mode --
  // every point on the shell is, by definition, (trochlea radius at
  // that position) + clearance, so correct clearance from the trochlea
  // is guaranteed rather than approximated. Verified against the real
  // geometry (built and sampled the actual mesh, not just eyeballed):
  // 0 clipping, minimum clearance 0.03. Also improved fit to the
  // olecranon/coronoid: both are now ~0.12-0.13 away (was 0.35-0.43).
  //
  // trochRadiusAt maps world_x -> trochlea surface radius there. This
  // is the trochlea's own profile re-expressed directly in world_x
  // (verified against the actual built trochlea mesh: world_x = 0.17 -
  // y_profile, so e.g. y_profile=0 (r=0.150) sits at world_x=+0.17,
  // not -0.17 as the naive reading of the profile array would suggest).
  const trochRadiusTable = [
    [-0.170, 0.150], [-0.130, 0.148], [-0.080, 0.128], [-0.020, 0.098],
    [0.000, 0.088], [0.020, 0.096], [0.080, 0.122], [0.140, 0.138], [0.170, 0.130]
  ];
  function trochRadiusAt(x) {
    if (x <= trochRadiusTable[0][0]) return trochRadiusTable[0][1];
    if (x >= trochRadiusTable[trochRadiusTable.length - 1][0]) return trochRadiusTable[trochRadiusTable.length - 1][1];
    for (let i = 0; i < trochRadiusTable.length - 1; i++) {
      const [x0, r0] = trochRadiusTable[i], [x1, r1] = trochRadiusTable[i + 1];
      if (x >= x0 && x <= x1) { const t = (x - x0) / (x1 - x0); return r0 + t * (r1 - r0); }
    }
  }
  const NOTCH_CLEARANCE = 0.05;
  const NOTCH_WALL = 0.11;
  const notchPhiStart = THREE.MathUtils.degToRad(35.0);
  const notchPhiLength = THREE.MathUtils.degToRad(255.0);
  const notchInnerPts = [];
  const notchOuterPts = [];
  for (let i = 0; i <= 24; i++) {
    const x = -0.17 + (0.34 * i / 24);
    const r = trochRadiusAt(x);
    notchInnerPts.push(new THREE.Vector2(r + NOTCH_CLEARANCE, 0.17 - x));
    notchOuterPts.push(new THREE.Vector2(r + NOTCH_CLEARANCE + NOTCH_WALL, 0.17 - x));
  }
  const notchGeo = new THREE.LatheGeometry(notchInnerPts, 32, notchPhiStart, notchPhiLength);
  notchGeo.translate(0, -0.17, 0);
  const notch = new THREE.Mesh(notchGeo, ivoryMat);
  notch.rotation.z = Math.PI / 2;
  notch.position.set(0, -0.72, 0.04);
  notch.castShadow = true;
  notch.receiveShadow = true;
  ulnaGroup.add(notch);

  // Contact shadow at the trochlea-notch groove -- the groove wraps
  // through 255 degrees, too curved for a single flat decal to follow
  // precisely, so this is a representative patch at the anterior
  // contact point (phi=90 in the same world_y=r*cos(phi), world_z=
  // r*sin(phi) convention already established and validated for the
  // trochlea/notch construction above), which is also the most visible
  // part of the joint from the default camera angle.
  const hingeContactShadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.16, 24),
    new THREE.MeshBasicMaterial({
      color: 0xcccccc, transparent: true, opacity: 0.20,  // MultiplyBlending ignores opacity: the colour sets the darkening (black rendered a solid black hole)
      blending: THREE.MultiplyBlending, side: THREE.DoubleSide, depthWrite: false
    })
  );
  hingeContactShadow.position.set(0, -0.72, 0.178);
  // no rotation needed -- CircleGeometry's default normal already
  // faces +Z (anterior), matching the groove's outward normal there
  // (verified directly against the geometry, not assumed)
  hingeContactShadow.raycast = () => {}; // decorative only -- must not intercept Inspect Mode clicks meant for the labeled Ulna/Articular Cartilage meshes it sits between
  ulnaGroup.add(hingeContactShadow);

  // The "back wall" of the notch -- same technique, offset further out,
  // giving the cup real thickness instead of an infinitely-thin shell.
  const notchBackGeo = new THREE.LatheGeometry(notchOuterPts, 32, notchPhiStart, notchPhiLength);
  notchBackGeo.translate(0, -0.17, 0);
  const notchBack = new THREE.Mesh(notchBackGeo, ivoryMat);
  notchBack.rotation.z = Math.PI / 2;
  notchBack.position.set(0, -0.72, 0.04);
  notchBack.castShadow = true;
  ulnaGroup.add(notchBack);

  // Thin cartilage lining directly on the inner (trochlea-facing) shell.
  const notchCartPts = notchInnerPts.map(p => new THREE.Vector2(p.x + 0.012, p.y));
  const notchCartGeo = new THREE.LatheGeometry(notchCartPts, 32, notchPhiStart, notchPhiLength);
  notchCartGeo.translate(0, -0.17, 0);
  const notchCart = new THREE.Mesh(notchCartGeo, cartMat);
  notchCart.rotation.z = Math.PI / 2;
  notchCart.position.set(0, -0.72, 0.04);
  ulnaGroup.add(notchCart);
  
  
  // (Ulna shaft: now the real ulna from Skeleton.obj -- see the
  // "RIGGED OBJ BONES" block below. The old cylinder is gone.)

  // (Radial notch removed: it sat at y=-0.08 -- up inside the humerus
  // shaft, not beside the radial head -- so it was hidden at rest and
  // floated free as a loose shard once the forearm flexed.)

  ulnaGroup.position.set(-HINGE_AXIS.x, -HINGE_AXIS.y, -HINGE_AXIS.z);  
  forearmPivot.add(ulnaGroup);  
  
  // ═══════════════════════════════════════════════════════════════  
  //  PROXIMAL RADIUS — head with concave top for capitulum  
  // ═══════════════════════════════════════════════════════════════  
  const radiusGroup = new THREE.Group();  
  
  // Radial head -- re-seated directly BELOW the capitulum, its axis along
  // the radius (vertical). It previously sat at the capitulum's own
  // centre height (y=-0.72, i.e. inside the capitulum) with its disc
  // turned to face forward (rotation.x=PI/2), and its cartilage/fovea at
  // x=0.34 rather than under the capitulum at x=0.50. The head's top
  // (with cartilage) is 0.16 from the flexion axis: just outside the
  // capitulum cartilage (0.152 below / 0.161 in front), so the head
  // glides round it through the full arc without cutting into it.
  const RAD_X = 0.50, RAD_Z = 0.04;
  const RAD_HEAD_TOP = -0.90;
  const radHeadGeo = new THREE.CylinderGeometry(0.13, 0.12, 0.10, 32);
  const radHead = new THREE.Mesh(radHeadGeo, ivoryMat);
  radHead.position.set(RAD_X, RAD_HEAD_TOP - 0.05, RAD_Z);
  radHead.castShadow = true;
  radiusGroup.add(radHead);

  // Radial head cartilage -- thin cap on the head's upper (articular) face
  const radHeadCartGeo = new THREE.CylinderGeometry(0.135, 0.135, 0.02, 32);
  const radHeadCart = new THREE.Mesh(radHeadCartGeo, cartMat);
  radHeadCart.position.set(RAD_X, RAD_HEAD_TOP + 0.01, RAD_Z);
  radiusGroup.add(radHeadCart);

  // Radial neck -- bridges the head to the real radius shaft below
  const radNeckGeo = new THREE.CylinderGeometry(0.085, 0.075, 0.20, 24);
  const radNeck = new THREE.Mesh(radNeckGeo, ivoryMat);
  radNeck.position.set(RAD_X, RAD_HEAD_TOP - 0.18, RAD_Z);
  radNeck.castShadow = true;
  radiusGroup.add(radNeck);

  // (Radius shaft: now the real radius from Skeleton.obj -- see below.)

  // Annular ligament -- ring around the radial head
  const annularLigGeo = new THREE.TorusGeometry(0.14, 0.018, 8, 32);
  const annularLig = new THREE.Mesh(annularLigGeo, ligMat);
  annularLig.position.set(RAD_X, RAD_HEAD_TOP - 0.05, RAD_Z);
  annularLig.rotation.x = Math.PI / 2;
  radiusGroup.add(annularLig);
  
  radiusGroup.position.set(-HINGE_AXIS.x, -HINGE_AXIS.y, -HINGE_AXIS.z);  
  forearmPivot.add(radiusGroup);  
  // ═══════════════════════════════════════════════════════════════
  //  RIGGED OBJ BONES -- humerus, ulna, radius and hand from Skeleton.obj
  //
  //  The articular region built above (trochlea, capitulum, epicondyles,
  //  trochlear notch, olecranon, coronoid, radial head, cartilage) is
  //  kept; the real bones supply everything else -- the humeral shaft
  //  and head, the ulna and radius shafts, and the hand skeleton (which
  //  replaces the old capsule-chain hand).
  //
  //  Placement: the OBJ's LEFT arm (this scene's lateral side is +X, so
  //  it is a left elbow seen from the front), rotated out of T-pose so
  //  distal points down (OBJ +X -> scene -Y, OBJ +Y -> scene +X lateral,
  //  +Z stays anterior), scale 8 scene units per metre. At that scale
  //  the OBJ humeral shaft matches the hand-built distal flare's width
  //  and the forearm matches the scene's previous forearm length.
  //
  //  Each bone is then re-seated rigidly (no bending/scaling) so its
  //  shaft runs into the matching hand-built end, and cut + capped where
  //  it enters that end so the low-poly OBJ joint surfaces never compete
  //  with the detailed ones:
  //    humerus: shaft axis made vertical through the flare (x=0.18)
  //    ulna:    proximal shaft into the base of the trochlear notch
  //    radius:  proximal shaft into the radial neck
  //  The wrist end of the forearm is shifted 0.15 laterally, giving a
  //  small carrying angle (forearm angled slightly away from the body in
  //  extension) instead of converging sharply under the wide condyles.
  //
  //  Rig: humerus is static; ulna + radius + hand are baked into
  //  forearmPivot's local frame, so they flex as one rigid unit about
  //  the trochlea/capitulum axis.
  // ═══════════════════════════════════════════════════════════════
  const V3 = (x,y,z) => new THREE.Vector3(x,y,z);
  const ARM_PLACE = {
    jointObj: V3(0.413, 1.417, -0.143),          // OBJ left elbow centre (metres)
    jointScene: HINGE_AXIS.clone(),
    scale: 8,
    basis: new THREE.Matrix4().makeRotationZ(-Math.PI/2)
  };
  const DISTAL_SHIFT = V3(0.15, 0, 0);

  const objHumerus = objBone('humerus', ivoryMat, ARM_PLACE);
  seatBone(objHumerus, V3(0.092,-0.145,0.026), V3(0.18,-0.145,0.0),
                       V3(0.110, 0.440,0.109), V3(0.18, 0.445,0.0));
  cutBoneAtY(objHumerus, -0.30, true);
  humerusGroup.add(objHumerus);

  const objUlna = objBone('ulna', ivoryMat, ARM_PLACE);
  seatBone(objUlna, V3(0.068,-2.81,-0.08), V3(0.068,-2.81,-0.08).add(DISTAL_SHIFT),
                    V3(0.056,-1.28,-0.156), V3(0.0,-1.28,-0.03));
  cutBoneAtY(objUlna, -0.96, false);

  const objRadius = objBone('radius', ivoryMat, ARM_PLACE);
  seatBone(objRadius, V3(0.109,-2.81,0.096), V3(0.109,-2.81,0.096).add(DISTAL_SHIFT),
                      V3(0.141,-1.19,0.016), V3(RAD_X,-1.19,RAD_Z));
  cutBoneAtY(objRadius, -1.10, false);

  const objHand = objBone('hand', ivoryMat, ARM_PLACE);
  objHand.geometry.translate(DISTAL_SHIFT.x, DISTAL_SHIFT.y, DISTAL_SHIFT.z);

  // built in world-at-rest coordinates above; move into the pivot frame
  [objUlna, objRadius, objHand].forEach(m => {
    m.geometry.translate(-HINGE_AXIS.x, -HINGE_AXIS.y, -HINGE_AXIS.z);
    forearmPivot.add(m);
  });  

  
  // ═══════════════════════════════════════════════════════════════  
  //  LIGAMENTS  
  // ═══════════════════════════════════════════════════════════════  
  // Ligaments — redesigned to run from the epicondyle down to the
  // forearm bones, matching real anatomy (they never reach anywhere
  // near the shaft). The previous path extended up toward the shaft/
  // condyle transition; even after being pulled back and recolored
  // earlier in this project, it still coincided with that silhouette
  // closely enough that Inspect Mode's highlight glow made it read as
  // a crack in the bone. Confining the path to where these ligaments
  // actually attach removes the coincidence at its source rather than
  // trying to out-tune the color or curve shape around it.
  const uclCurve = new THREE.CatmullRomCurve3([  
    new THREE.Vector3(-0.155, -0.55, 0.00),  
    new THREE.Vector3(-0.18, -0.60, 0.06),  
    new THREE.Vector3(-0.14, -0.65, 0.13),  
    new THREE.Vector3(-0.05, -0.68, 0.17)  
  ]);  
  const uclGeo = new THREE.TubeGeometry(uclCurve, 20, 0.032, 8, false);  
  const ucl = new THREE.Mesh(uclGeo, ligMat);  
  group.add(ucl);  
  const uclFlares = createLigamentFanCaps([  
    [-0.155, -0.55, 0.00], [-0.18, -0.60, 0.06], [-0.14, -0.65, 0.13], [-0.05, -0.68, 0.17]  
  ], 0.032, ligMat);  
  group.add(...uclFlares);  
  
  const rclCurve = new THREE.CatmullRomCurve3([  
    new THREE.Vector3(0.38, -0.55, 0.00),  
    new THREE.Vector3(0.40, -0.62, 0.03),  
    new THREE.Vector3(0.38, -0.68, 0.06),  
    new THREE.Vector3(0.35, -0.72, 0.06)  
  ]);  
  const rclGeo = new THREE.TubeGeometry(rclCurve, 20, 0.028, 8, false);  
  const rcl = new THREE.Mesh(rclGeo, ligMat);  
  group.add(rcl);  
  const rclFlares = createLigamentFanCaps([  
    [0.38, -0.55, 0.00], [0.40, -0.62, 0.03], [0.38, -0.68, 0.06], [0.35, -0.72, 0.06]  
  ], 0.028, ligMat);  
  group.add(...rclFlares);  
  
  // Joint capsule  
  const capsuleShape = new THREE.SphereGeometry(0.52, 24, 24, 0, Math.PI * 2, 0, Math.PI);  
  const capsuleMesh = new THREE.Mesh(capsuleShape, new THREE.MeshPhysicalMaterial({  
    color: 0xc8b8a8, roughness: 0.95, metalness: 0.0,  
    transparent: true, opacity: 0.28, side: THREE.DoubleSide, depthWrite: false  
  }));  
  capsuleMesh.scale.set(1.10, 0.78, 0.88);  
  capsuleMesh.position.set(0, -0.36, 0.02);  
  group.add(capsuleMesh);  
  
  scene.add(group);
  camera.position.set(4.5, 1.2, 5.5);
  
  const MIN_ANGLE = 0;  
  const MAX_ANGLE = 2.62;  
  let currentAngle = 0;  
  let targetAngle = 0;  
  const damping = 0.04;  
  
  function anim(t){  
    group.rotation.y = Math.sin(t * 0.04) * 0.08;  
    const rawTarget = (Math.sin(t * 0.35) * 0.5 + 0.5) * MAX_ANGLE;  
    targetAngle = rawTarget;  
    currentAngle += (targetAngle - currentAngle) * damping;  
    currentAngle = Math.max(MIN_ANGLE, Math.min(MAX_ANGLE, currentAngle));  
    forearmPivot.rotation.x = -currentAngle;
    forearmPivot.rotation.y = 0;  
    forearmPivot.rotation.z = 0;  
    const tension = currentAngle / MAX_ANGLE;  
    ucl.scale.y = 1 + tension * 0.12;  
    rcl.scale.y = 1 + tension * 0.10;  
  }  
  
  const inspectables = [
    {mesh: humerusBody, label:'Humerus', desc:'Upper arm bone. Its lower end forms the elbow joint with the ulna and radius.'},
    {mesh: objHumerus, label:'Humerus', desc:'Upper arm bone. Its lower end forms the elbow joint with the ulna and radius.'},
    {mesh: objUlna, label:'Ulna', desc:'Forearm bone on the little-finger side. Forms the main hinge of the elbow.'},
    {mesh: objRadius, label:'Radius', desc:'Forearm bone on the thumb side. Rotates alongside the ulna during forearm movement.'},
    {mesh: trochlea, label:'Trochlea', desc:'Spool-shaped part of the humerus. Fits into the ulna\'s trochlear notch and guides the hinge motion.'},
    {mesh: capitulum, label:'Capitulum', desc:'Rounded part of the humerus, beside the trochlea. Articulates with the head of the radius.'},
    {mesh: olecranon, label:'Olecranon Process', desc:'The bony point of the ulna that forms the tip of the elbow. Locks into place behind the humerus during extension.'},
    {mesh: olecranonTip, label:'Olecranon Process', desc:'The bony point of the ulna that forms the tip of the elbow. Locks into place behind the humerus during extension.'},
    {mesh: notch, label:'Trochlear Notch', desc:'C-shaped curve on the ulna that wraps around the humerus\'s trochlea, forming the main hinge surface.'},
    {mesh: trochCart, label:'Articular Cartilage', desc:'Smooth tissue covering bone ends. Reduces friction and cushions the joint during movement.'},
    {mesh: capCart, label:'Articular Cartilage', desc:'Smooth tissue covering bone ends. Reduces friction and cushions the joint during movement.'},
    {mesh: notchCart, label:'Articular Cartilage', desc:'Smooth tissue covering bone ends. Reduces friction and cushions the joint during movement.'},
    {mesh: radHeadCart, label:'Articular Cartilage', desc:'Smooth tissue covering bone ends. Reduces friction and cushions the joint during movement.'},
    {mesh: olecranonCart, label:'Articular Cartilage', desc:'Smooth tissue covering bone ends. Reduces friction and cushions the joint during movement.'},
    {mesh: ucl, label:'Ligament', desc:'Tough fibrous tissue connecting bone to bone. Stabilizes the joint and limits excess movement.'},
    {mesh: rcl, label:'Ligament', desc:'Tough fibrous tissue connecting bone to bone. Stabilizes the joint and limits excess movement.'},
    {mesh: annularLig, label:'Ligament', desc:'Tough fibrous tissue connecting bone to bone. Stabilizes the joint and limits excess movement.'}
  ];
  return {scene, camera, renderer, controls, anim, inspectables};  
}  
/* ─── 6. PIVOT — Atlas–Axis (C1–C2) ───
   Real vertebrae from BodyParts3D (CC BY 4.0, (c) Database Center for
   Life Science -- see "About this Simulation"): atlas (C1), axis (C2)
   and C3, at 22 scene units per metre. Frame: +X = subject's left,
   +Y up, +Z anterior.

   Rig: the atlas turns about the DENS's own axis, measured from the
   axis mesh (centre at x=-0.4 mm, z=-24.5 mm; tilted ~11 deg backwards,
   as the real dens is). c1Pivot sits on that axis with its local Y
   along it, so rotating c1Pivot about local Y is exactly atlanto-axial
   rotation ("no" movement) -- about 30 deg each way here (~40 deg
   is the real maximum). The transverse ligament belongs to the atlas
   (it spans between the atlas's lateral masses), so it is in the
   pivot too: it stays wrapped behind the dens as the ring turns. */
function buildPivot(){  
  const {scene, camera, renderer, controls} = initBaseScene();  
  const group = new THREE.Group();  
  const V3 = (x,y,z) => new THREE.Vector3(x,y,z);

  const ivoryMat = new THREE.MeshPhysicalMaterial({  
    map: boneTex.albedo, bumpMap: boneTex.bump, bumpScale: 0.02,  
    roughnessMap: boneTex.rough, roughness: 0.72, metalness: 0.04,  
    clearcoat: 0.2, clearcoatRoughness: 0.55,  
    color: 0xece4d8, side: THREE.FrontSide  
  });  
  // Atlas a little paler/greyer than the axis so the two bones read apart
  const atlasMat = new THREE.MeshPhysicalMaterial({  
    map: boneTex.albedo, bumpMap: boneTex.bump, bumpScale: 0.02,  
    roughnessMap: boneTex.rough, roughness: 0.75, metalness: 0.03,  
    clearcoat: 0.15, clearcoatRoughness: 0.6,  
    color: 0xcfd2d4, side: THREE.FrontSide  
  });  
  const facetMat = new THREE.MeshPhysicalMaterial({  
    color: 0xc8e0ec, roughness: 0.18, metalness: 0.0,  
    transmission: 0.5, thickness: 0.8, ior: 1.41,  
    transparent: true, opacity: 0.78, side: THREE.DoubleSide,  
    clearcoat: 0.5, clearcoatRoughness: 0.1,  
    envMap: sharedCartilageEnvMap || null, envMapIntensity: 0.7  
  });  
  const ligMat = new THREE.MeshPhysicalMaterial({  
    color: 0xfafcfe, roughness: 0.7, metalness: 0.0,  
    bumpMap: ligamentTex, bumpScale: 0.01,  
    transparent: true, opacity: 0.95, side: THREE.DoubleSide  
  });  

  const S = 22;
  const DENS_OBJ = V3(-0.0004, 1.548, -0.0245);          // point on the dens axis (metres)
  const PIVOT_POS = V3(0, 0.5, 0);                       // where that point sits in the scene
  const PLACE = {jointObj: DENS_OBJ, jointScene: PIVOT_POS, scale: S, basis: new THREE.Matrix4()};
  const DENS_DIR = V3(0, 0.982, -0.19).normalize();      // dens axis, tilted ~11 deg posteriorly

  // ─── AXIS (C2) and C3: static ───
  const axisBone = objBone('bp_axis', ivoryMat, PLACE);
  const c3 = objBone('bp_c3', ivoryMat, PLACE);
  group.add(axisBone, c3);

  // ─── ATLAS (C1): rigged on the dens axis ───
  const c1Pivot = new THREE.Group();
  c1Pivot.position.copy(PIVOT_POS);
  const pivotBaseQ = new THREE.Quaternion().setFromUnitVectors(V3(0,1,0), DENS_DIR);
  c1Pivot.quaternion.copy(pivotBaseQ);
  group.add(c1Pivot);
  const toPivot = new THREE.Matrix4().compose(PIVOT_POS, pivotBaseQ, V3(1,1,1)).invert();
  const atlas = objBone('bp_atlas', atlasMat, PLACE);
  atlas.geometry.applyMatrix4(toPivot);                  // bake into the pivot's local frame
  atlas.geometry.computeVertexNormals();
  c1Pivot.add(atlas);

  // Transverse ligament: arcs BEHIND the dens between the inner walls of
  // the lateral masses (measured at +-9.5 mm), hugging the dens (whose
  // back reaches ~7.4 mm from its axis; the band's inner face clears it) -- it is what keeps the dens against the anterior arch.
  // Built in pivot-local coordinates (dens axis = local Y, centre = 0).
  const ligPts = [];
  [[-15,11.2],[-45,9.6],[-70,9.4],[-90,9.4],[-110,9.4],[-135,9.6],[-165,11.2]].forEach(([deg, rmm]) => {
    const a = THREE.MathUtils.degToRad(deg), r = rmm*0.001*S;
    ligPts.push(V3(r*Math.cos(a), 0.0, -r*Math.sin(a) * -1));   // deg<0 -> posterior (-Z)
  });
  const transverseLigament = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(ligPts), 40, 0.028, 10, false), ligMat);
  transverseLigament.scale.set(1, 2.2, 1);              // a flat band, taller than it is thick
  c1Pivot.add(transverseLigament);

  // Median atlanto-axial joint: cartilage film between the front of the
  // dens and the facet on the back of the anterior arch (a synovial joint).
  const densFacet = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0062*S, 0.0062*S, 0.009*S, 32, 1, true, -Math.PI*0.28, Math.PI*0.56), facetMat);
  densFacet.position.set(0, 0.001*S, 0);
  c1Pivot.add(densFacet);                                // rides with the atlas facet

  scene.add(group);  
  camera.position.set(2.6, 3.4, 3.4);  
  controls.target.set(0, 0.25, 0);
  const _rot = new THREE.Quaternion();
  function anim(t){  
    _rot.setFromAxisAngle(V3(0,1,0), Math.sin(t * 0.6) * 0.55);
    c1Pivot.quaternion.copy(pivotBaseQ).multiply(_rot);  // turn about the dens axis
  }  

  const inspectables = [
    {mesh: atlas, label:'Atlas (C1)', desc:'The topmost neck vertebra: a ring with no body. It carries the skull, and the two turn together around the dens of the axis.'},
    {mesh: axisBone, label:'Axis (C2)', desc:'The second neck vertebra. Its upward peg, the dens (odontoid process), is the pivot that the atlas and skull rotate around.'},
    {mesh: c3, label:'Third Cervical Vertebra (C3)', desc:'A typical neck vertebra below the axis, shown for context.'},
    {mesh: transverseLigament, label:'Transverse Ligament', desc:'Holds the dens firmly against the atlas, keeping rotation safe and controlled.'},
    {mesh: densFacet, label:'Articular Cartilage', desc:'Lines the joint between the front of the dens and the atlas, letting the ring glide around the peg.'}
  ];
  return {scene, camera, renderer, controls, anim, inspectables};  
}  
  
/* ─── DATA & ROUTING ─── */  
const BUILDERS = {  
  fixed: buildFixed,  
  slightly: buildSlightly,  
  freely: buildFreely,  
  ballsocket: buildBallSocket,  
  hinge: buildHinge,  
  pivot: buildPivot  
};  

/* ═══════════════════════════════════════════════════════════════
   INSPECT MODE — isolated, additive module.

   Does not modify show(), loop(), disposeCurrent(), OrbitControls,
   the camera system, or scene hierarchy. It works entirely by:
     1. Wrapping each BUILDERS[key] once, at load time, so a scene's
        returned anim() is pause-aware and its `inspectables` list
        (added to 4 of the 6 builders -- see their return statements)
        is captured for raycasting.
     2. Adding one click listener to the shared canvas that only
        acts when Inspect Mode is on.
   Everything else in the simulator runs exactly as it did before.
   ═══════════════════════════════════════════════════════════════ */
(function setupInspectMode(){

  let inspectModeActive = false;

  // --- Pause/resume without touching the render loop ---
  // Freezes the animation's time input the instant Inspect Mode turns
  // on (so the joint holds exactly its current pose), and on resume,
  // shifts all future time values back by the paused duration so the
  // animation continues smoothly from that same pose rather than
  // jumping forward to "catch up" to real elapsed time.
  let pauseStartRawT = null;
  let totalPausedDuration = 0;

  function wrapAnim(originalAnimFn){
    if (typeof originalAnimFn !== 'function') return originalAnimFn;
    return function(rawT){
      if (inspectModeActive){
        if (pauseStartRawT === null) pauseStartRawT = rawT;
        originalAnimFn(pauseStartRawT - totalPausedDuration);
      } else {
        if (pauseStartRawT !== null){
          totalPausedDuration += (rawT - pauseStartRawT);
          pauseStartRawT = null;
        }
        originalAnimFn(rawT - totalPausedDuration);
      }
    };
  }

  // --- Highlight state (single selection, shared materials preserved) ---
  // Many meshes in this simulator share ONE material instance across
  // several objects (e.g. every bone-colored mesh in a joint). Setting
  // emissive directly on mesh.material would highlight every mesh
  // sharing that instance, not just the tapped one -- so instead we
  // swap in a per-mesh clone for the highlight and restore the
  // original shared reference (never mutated) when deselecting.
  let selectedMesh = null;
  let selectedOriginalMaterial = null;

  function clearHighlight(){
    if (selectedMesh && selectedOriginalMaterial){
      const highlightClone = selectedMesh.material;
      selectedMesh.material = selectedOriginalMaterial;
      if (highlightClone && highlightClone !== selectedOriginalMaterial) highlightClone.dispose();
    }
    selectedMesh = null;
    selectedOriginalMaterial = null;
  }

  function highlightMesh(mesh){
    if (mesh === selectedMesh) return; // already selected, nothing to do
    clearHighlight();
    selectedOriginalMaterial = mesh.material;
    const clone = mesh.material.clone();
    clone.emissive = new THREE.Color(0xe8c468);
    clone.emissiveIntensity = 0.5;
    mesh.material = clone;
    selectedMesh = mesh;
  }

  // --- Info card (bottom sheet, anchored to the 3D viewport) ---
  function showInfoCard(label, desc){
    const card = document.getElementById('inspectCard');
    const titleEl = document.getElementById('inspectCardTitle');
    const descEl = document.getElementById('inspectCardDesc');
    if (!card || !titleEl || !descEl) return;
    titleEl.textContent = label;
    descEl.textContent = desc;
    card.classList.add('visible');
  }
  function hideInfoCard(){
    const card = document.getElementById('inspectCard');
    if (card) card.classList.remove('visible');
  }

  // --- Raycasting ---
  // Reused across every click rather than recreated each time, and
  // raycasting only runs against the current joint's known inspectable
  // meshes (not the whole scene graph), which is both more accurate
  // and cheaper than a full-scene raycast plus fuzzy matching.
  const raycaster = new THREE.Raycaster();
  const pointerNDC = new THREE.Vector2();
  let currentInspectables = [];

  function performInspectHitTest(clientX, clientY){
    if (!inspectModeActive || !currentRenderer || !currentCamera || !currentScene) return;
    if (!currentInspectables.length) return;
    const rect = currentRenderer.domElement.getBoundingClientRect();
    pointerNDC.x = ((clientX - rect.left) / rect.width) * 2 - 1;
    pointerNDC.y = -((clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(pointerNDC, currentCamera);
    // Raycast the WHOLE scene (not just the labeled meshes) so unlabeled
    // geometry still correctly occludes what's behind it -- otherwise a
    // click that visually lands on something unlabeled (a hand bone, the
    // capsule, the scapula) is invisible to hit-testing and "sees
    // through" to whatever labeled structure happens to be further
    // along the same ray, mislabeling what the user actually tapped.
    const hits = raycaster.intersectObjects(currentScene.children, true);
    if (hits.length){
      const hitMesh = hits[0].object;
      const entry = currentInspectables.find(item => item.mesh === hitMesh);
      if (entry){
        highlightMesh(hitMesh);
        showInfoCard(entry.label, entry.desc);
      } else {
        clearHighlight();
        hideInfoCard();
      }
    } else {
      clearHighlight();
      hideInfoCard();
    }
  }

  let lastTouchHandledTime = 0;
  function handleCanvasClick(e){
    // Skip if a touch tap just handled this same interaction -- mobile
    // browsers synthesize a 'click' after a tap, and without this guard
    // that synthetic click would redundantly re-run the same hit test a
    // moment after handleTouchEnd already did.
    if (Date.now() - lastTouchHandledTime < 500) return;
    performInspectHitTest(e.clientX, e.clientY);
  }

  // --- Touch support ---
  // 'click' already fires after a tap on most mobile browsers, so the
  // handler above works on touch devices in the common case. This adds
  // explicit touch handling as a more robust primary path: it only acts
  // on a genuine TAP (minimal movement between touchstart and touchend),
  // so a drag meant for OrbitControls' own rotate/pan can't be
  // misread as a selection. Listeners are passive and never call
  // preventDefault, so OrbitControls' own touch handling on the same
  // canvas is completely unaffected.
  let touchStartPos = null;
  const TAP_MOVE_THRESHOLD = 10; // px

  function handleTouchStart(e){
    if (!inspectModeActive || e.touches.length !== 1){ touchStartPos = null; return; } // ignore multi-touch (pinch/zoom)
    touchStartPos = {x: e.touches[0].clientX, y: e.touches[0].clientY};
  }
  function handleTouchEnd(e){
    if (!inspectModeActive || !touchStartPos) return;
    const touch = e.changedTouches[0];
    if (!touch) { touchStartPos = null; return; }
    const dx = touch.clientX - touchStartPos.x;
    const dy = touch.clientY - touchStartPos.y;
    if (Math.sqrt(dx*dx + dy*dy) < TAP_MOVE_THRESHOLD){
      performInspectHitTest(touch.clientX, touch.clientY);
      lastTouchHandledTime = Date.now();
    }
    touchStartPos = null;
  }

  // The canvas is created once and shared for the whole session (see
  // getSharedRenderer), so this listener only needs attaching once --
  // it checks inspectModeActive itself, so it's harmless when off.
  //
  // Takes the renderer as a parameter rather than reading the global
  // currentRenderer: at the moment this runs (inside the builder
  // wrapper below), show() hasn't assigned currentRenderer yet -- that
  // happens only after builder() returns. Reading the global here would
  // silently fail to attach on the very first joint shown each session
  // (found via testing, not by inspection -- currentRenderer is null
  // on that first call).
  let clickListenerAttached = false;
  function ensureClickListenerAttached(renderer){
    if (clickListenerAttached || !renderer) return;
    renderer.domElement.addEventListener('click', handleCanvasClick);
    renderer.domElement.addEventListener('touchstart', handleTouchStart, {passive:true});
    renderer.domElement.addEventListener('touchend', handleTouchEnd, {passive:true});
    clickListenerAttached = true;
  }

  // --- Wrap every builder once, at load time ---
  Object.keys(BUILDERS).forEach(function(key){
    const originalBuilder = BUILDERS[key];
    BUILDERS[key] = function(){
      const sceneData = originalBuilder();
      if (sceneData && sceneData.anim) sceneData.anim = wrapAnim(sceneData.anim);
      // A new joint means the previous selection's mesh no longer
      // belongs to the live scene -- drop it rather than let it dangle.
      clearHighlight();
      hideInfoCard();
      currentInspectables = (sceneData && sceneData.inspectables) || [];
      if (sceneData) ensureClickListenerAttached(sceneData.renderer);
      return sceneData;
    };
  });

  // --- Toggle button ---
  window.toggleInspectMode = function(){
    inspectModeActive = !inspectModeActive;
    const btn = document.getElementById('inspectToggle');
    if (btn) btn.classList.toggle('active', inspectModeActive);
    if (!inspectModeActive){
      clearHighlight();
      hideInfoCard();
    }
  };

})();

  
const DATA={  
  fixed:{  
    icn:'&#9724;',ttl:'Fixed Joint (Fibrous)',sub:'Synarthrosis',  
    dsc:'Bones are joined by strong fibrous connective tissue and do not move. These joints mainly protect delicate organs, especially the brain. Skull bones are connected by sutures.',  
    examples:['Coronal suture','Sagittal suture','Lambdoid suture','Squamous suture','Gomphosis (tooth in socket)'],  
    movement:'No movement.'  
  },  
  slightly:{  
    icn:'&#9723;',ttl:'Cartilaginous Joint',sub:'Amphiarthrosis',  
    dsc:'Bones are joined by cartilage. These joints allow slight movement and help absorb shock during movement.',  
    examples:['Between vertebrae','Pubic symphysis','First rib–sternum'],  
    movement:'Limited movement.'  
  },  
  freely:{  
    icn:'&#9673;',ttl:'Synovial Joint',sub:'Diarthrosis',  
    dsc:'Bones are separated by a fluid-filled joint cavity. Smooth cartilage and synovial fluid reduce friction, allowing free movement.',  
    examples:['Shoulder','Hip','Knee','Elbow','Wrist','Ankle'],  
    movement:'Freely movable.'  
  },  
  ballsocket:{  
    icn:'&#9673;',ttl:'Ball-and-Socket Joint',sub:'Multiaxial',  
    dsc:'A rounded bone fits into a cup-shaped socket, allowing movement in all directions.',  
    examples:['Shoulder','Hip'],  
    movement:'Movement in all directions, including rotation.'  
  },  
  pivot:{  
    icn:'&#8853;',ttl:'Pivot Joint',sub:'Uniaxial',  
    dsc:'One bone rotates around another, allowing rotation only.',  
    examples:['Neck (atlas–axis)','Radius and ulna'],  
    movement:'Rotation.'  
  },  
  hinge:{  
    icn:'&#8867;',ttl:'Hinge Joint',sub:'Uniaxial',  
    dsc:'Works like the hinge of a door. Movement is possible in one direction only.',  
    examples:['Elbow','Knee','Ankle','Fingers'],  
    movement:'Flexion and extension.'  
  }  
};  
  
/* ─── ACCORDION TOGGLE ─── */  
window.toggleAccordion = function(id) {  
  const item = document.getElementById(id);  
  if(!item) return;  
  item.classList.toggle('open');  
};  
  
/* ─── MAIN SHOW FUNCTION ─── */  
window.show = function(type){  
  const sub = document.getElementById('submenu');  
  if(type==='freely') sub.style.display='flex';  
  else if(!['ballsocket','pivot','hinge'].includes(type)) sub.style.display='none';  
  
  const d = DATA[type]; if(!d) return;  
  const c = document.getElementById('card'); c.style.display='block';  
  document.getElementById('icn').innerHTML = d.icn;  
  document.getElementById('ttl').textContent = d.ttl;  
  document.getElementById('sub').textContent = d.sub;  
  document.getElementById('dsc').textContent = d.dsc;  
  document.getElementById('mov').textContent = d.movement;  
  
  const ul = document.getElementById('exm'); ul.innerHTML='';  
  d.examples.forEach(e=>{ const li=document.createElement('li'); li.textContent=e; ul.appendChild(li); });  
  
  ['acc-desc','acc-exm','acc-mov'].forEach(id => {  
    const el = document.getElementById(id);  
    if(el) el.classList.add('open');  
  });  
  
  disposeCurrent();  
  
  const builder = BUILDERS[type];  
  if(builder){  
    try{  
      const sceneData = builder();  
      currentScene = sceneData.scene;  
      currentCamera = sceneData.camera;  
      currentRenderer = sceneData.renderer;  
      currentControls = sceneData.controls;  
      const animFn = sceneData.anim;  
  
      function loop(){  
        try{  
          animId = requestAnimationFrame(loop);  
          const t = clock.getElapsedTime();  
          if(animFn) animFn(t);  
          // safety net for rotation: re-fit if the panel size changed and
          // neither 'resize' nor the ResizeObserver has caught it yet
          if(currentRenderer && (currentRenderer.domElement.width !== Math.round(dia.clientWidth*currentRenderer.getPixelRatio()) || currentRenderer.domElement.height !== Math.round(dia.clientHeight*currentRenderer.getPixelRatio()))) onViewportResize();
          if(currentControls) currentControls.update();  
          if(currentRenderer && currentScene && currentCamera){  
            currentRenderer.render(currentScene, currentCamera);  
          }  
        }catch(err){  
          if(animId) cancelAnimationFrame(animId);  
          showDiagError(err);  
        }  
      }  
      loop();  
    }catch(err){  
      showDiagError(err);  
    }  
  }  
  
  c.scrollIntoView({behavior:'smooth', block:'nearest'});  
};  
  
function showDiagError(err){  
  console.error('3D view error:', err);  
  const box = document.createElement('div');  
  box.style.cssText = 'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:16px;color:#e08080;font-size:11px;font-family:monospace;white-space:pre-wrap;text-align:left;overflow:auto;z-index:30;background:rgba(5,5,8,0.95);';  
  box.textContent = '3D render error:\n' + (err && err.stack ? err.stack : String(err));  
  dia.appendChild(box);  
}  
  
// Resize handler. Also driven by a ResizeObserver on the viewport itself:
// on phones the window 'resize' event can arrive before the rotated layout
// is applied (or not at all), which left the picture stretched at the old
// aspect ratio until the next resize. Observing the panel catches every
// real size change, including CSS breakpoint changes.
function onViewportResize(){  
  if(currentCamera && currentRenderer){  
    const w = dia.clientWidth, h = dia.clientHeight;  
    if(!w || !h) return;
    currentCamera.aspect = w/h;  
    currentCamera.updateProjectionMatrix();  
    currentRenderer.setSize(w, h);  
  }  
}
window.addEventListener('resize', onViewportResize);  
if (typeof ResizeObserver !== 'undefined') new ResizeObserver(onViewportResize).observe(dia);
  
// Module finished loading — hand off from the early stub to the real  
// show(), replaying whatever the user clicked while it was loading.  
// No default fallback: the card stays hidden until the user explicitly  
// picks a joint type (previously this defaulted to show('freely'),  
// which is why the Synovial Joint card was appearing on every load  
// regardless of the flowchart's own hidden/revealed state).  
if (window.__pendingShow) {  
  show(window.__pendingShow);  
}  

/* ─── SUBMENU BAR + ABOUT CARD ─── */
  // Positions the submenu's horizontal branch bar to span exactly from
  // the first button's real center to the last button's real center,
  // measured via getBoundingClientRect rather than guessed in CSS --
  // "Ball & Socket" is meaningfully wider than "Pivot" or "Hinge", so
  // no fixed CSS value worked correctly for all three simultaneously
  // (confirmed by two separate rendering bugs against real
  // screenshots). Runs via ResizeObserver on .submenu-row itself, which
  // fires whenever the row's size changes -- including when it goes
  // from display:none to visible, and on any window resize/orientation
  // change -- so this needs no hook into show() or any other existing
  // logic.
  function updateSubmenuBar(){
    var row = document.querySelector('.submenu-row');
    if (!row) return;
    var buttons = row.querySelectorAll('.sub-btn');
    if (buttons.length < 2) return;
    var rowRect = row.getBoundingClientRect();
    if (rowRect.width === 0) return; // hidden -- nothing to measure yet
    var firstRect = buttons[0].getBoundingClientRect();
    var lastRect = buttons[buttons.length - 1].getBoundingClientRect();
    var firstCenter = (firstRect.left + firstRect.right) / 2 - rowRect.left;
    var lastCenter = (lastRect.left + lastRect.right) / 2 - rowRect.left;
    var bar = document.getElementById('submenuBar');
    if (!bar) {
      bar = document.createElement('div');
      bar.id = 'submenuBar';
      row.appendChild(bar);
    }
    bar.style.left = firstCenter + 'px';
    bar.style.width = (lastCenter - firstCenter) + 'px';
  }
  if (typeof ResizeObserver !== 'undefined') {
    var submenuRowEl = document.querySelector('.submenu-row');
    if (submenuRowEl) new ResizeObserver(updateSubmenuBar).observe(submenuRowEl);
  }
  window.addEventListener('resize', updateSubmenuBar);
  updateSubmenuBar();
  (function(){
    var KEY = 'infoCardOpen';
    var card = document.getElementById('infoCard');
    window.toggleInfoCard = function(){
      card.classList.toggle('open');
      try { localStorage.setItem(KEY, card.classList.contains('open') ? '1' : '0'); } catch(e){}
    };
    try {
      if (localStorage.getItem(KEY) === '1') card.classList.add('open');
    } catch(e){}
  })();
